const express=require('express'),jwt=require('jsonwebtoken'),bcrypt=require('bcryptjs'),multer=require('multer'),fs=require('fs'),path=require('path'),crypto=require('crypto');
const db=require('./db');
const app=express(),PORT=process.env.PORT||3000,SECRET=process.env.JWT_SECRET||'dev-secret-change-me';
const root=path.join(__dirname,'..'),uploads=path.join(root,'uploads');fs.mkdirSync(uploads,{recursive:true});
const upload=multer({dest:uploads,limits:{fileSize:20*1024*1024}});
app.use(express.json({limit:'5mb'}));app.use(express.urlencoded({extended:true}));app.use(express.static(path.join(root,'public')));app.use('/uploads',express.static(uploads));
app.use('/api',(req,res,next)=>{res.set('Cache-Control','no-store, no-cache, must-revalidate, proxy-revalidate');res.set('Pragma','no-cache');res.set('Expires','0');next();});
const roles={
 'CEO / Owner':['*'],
 'Operations Manager':['dashboard','staff','tasks','reports','kpi','meetings','businesses','inventory','finance','approvals','crm','documents','sales','pos','restaurant'],
 'Finance / Admin':['dashboard','finance','approvals','documents','reports','sales','purchases','inventory'],
 'Sales / Business Development':['dashboard','tasks','crm','kpi','documents','sales','customers'],
 'Business Unit Manager':['dashboard','tasks','staff','reports','kpi','inventory','finance','meetings','sales','purchases','crm','documents','pos','restaurant'],
 'Staff Member':['dashboard','tasks','reports','documents','inventory']};
function tok(u){return{id:u.id,name:u.name,email:u.email,role:u.role,business_unit_id:u.business_unit_id};}
function auth(req,res,next){const h=req.headers.authorization||'';if(!h.startsWith('Bearer '))return res.status(401).json({error:'Authentication required'});try{req.user=jwt.verify(h.slice(7),SECRET);const requested=req.headers['x-business-unit-id'];if(req.user.role==='CEO / Owner'){req.selected_business_unit_id=requested?Number(requested):null;if(requested && !db.prepare('SELECT id FROM business_units WHERE id=? AND status!=\'Archived\'').get(req.selected_business_unit_id))return res.status(400).json({error:'Invalid business unit selection'});}else{req.selected_business_unit_id=req.user.business_unit_id||null;if(requested && Number(requested)!==Number(req.selected_business_unit_id))return res.status(403).json({error:'You cannot access another business unit'});}next();}catch(e){res.status(401).json({error:'Invalid or expired session'});}}
function allow(...p){return(req,res,next)=>{if(req.user.role==='CEO / Owner'||(roles[req.user.role]||[]).includes('*')||p.some(x=>(roles[req.user.role]||[]).includes(x)))return next();res.status(403).json({error:'You do not have permission for this action'});};}
function audit(u,e,id,a,d=''){db.prepare('INSERT INTO audit_log(user_id,entity,entity_id,action,details) VALUES(?,?,?,?,?)').run(u?.id||null,e,id||null,a,d);}
function notify(uid,level,title,message){db.prepare('INSERT INTO notifications(user_id,level,title,message) VALUES(?,?,?,?)').run(uid||null,level,title,message);}
function unitScope(req,field='business_unit_id'){if(req.selected_business_unit_id)return{sql:` AND ${field}=?`,args:[req.selected_business_unit_id]};if(req.user.role==='CEO / Owner')return{sql:'',args:[]};if(req.user.business_unit_id)return{sql:` AND ${field}=?`,args:[req.user.business_unit_id]};return{sql:' AND 1=0',args:[]};}
function enforceUnit(req,businessUnitId){if(req.user.role==='CEO / Owner'){if(req.selected_business_unit_id && Number(businessUnitId)!==Number(req.selected_business_unit_id))return false;return true;}return Number(businessUnitId)===Number(req.user.business_unit_id);}
function currentUnit(req){return req.selected_business_unit_id||req.user.business_unit_id||null;}
function uid(){return crypto.randomBytes(24).toString('hex');}
function num(v){return Number(v||0);}
function nextNo(prefix,table,col){const n=db.prepare(`SELECT COUNT(*) c FROM ${table}`).get().c+1;return `${prefix}-${new Date().getFullYear()}-${String(n).padStart(5,'0')}`;}

app.get('/api/health',(req,res)=>res.json({ok:true,version:'24.8.0'}));
app.post('/api/auth/login',(req,res)=>{const {email,password}=req.body||{};const u=db.prepare('SELECT * FROM users WHERE lower(email)=lower(?) AND active=1').get(email||'');if(!u||!bcrypt.compareSync(password||'',u.password_hash))return res.status(401).json({error:'Invalid email or password'});const t=jwt.sign(tok(u),SECRET,{expiresIn:'12h'});audit(u,'auth',u.id,'login');res.json({token:t,user:tok(u)});});
app.post('/api/auth/forgot',(req,res)=>{const u=db.prepare('SELECT * FROM users WHERE lower(email)=lower(?) AND active=1').get(req.body.email||'');if(!u)return res.json({message:'If the account exists, a reset link has been created.'});const token=uid();db.prepare('INSERT INTO password_resets(user_id,token,expires_at) VALUES(?,?,datetime(\'now\',\'+30 minutes\'))').run(u.id,token);const base=`${req.protocol}://${req.get('host')}`;res.json({message:'Reset link created.',reset_url:`${base}/?reset=${token}`});});
app.post('/api/auth/reset',(req,res)=>{const r=db.prepare('SELECT * FROM password_resets WHERE token=? AND used=0 AND datetime(expires_at)>datetime(\'now\')').get(req.body.token||'');if(!r)return res.status(400).json({error:'Reset token is invalid or expired'});if(!req.body.password||req.body.password.length<8)return res.status(400).json({error:'Password must be at least 8 characters'});db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(bcrypt.hashSync(req.body.password,12),r.user_id);db.prepare('UPDATE password_resets SET used=1 WHERE id=?').run(r.id);res.json({ok:true});});
app.get('/api/me',auth,(req,res)=>res.json({user:req.user}));
app.put('/api/me/profile',auth,(req,res)=>{const name=String(req.body.name||'').trim();const email=String(req.body.email||'').trim().toLowerCase();if(!name||!email)return res.status(400).json({error:'Name and email are required'});const exists=db.prepare('SELECT id FROM users WHERE lower(email)=lower(?) AND id<>?').get(email,req.user.id);if(exists)return res.status(400).json({error:'Email is already in use'});db.prepare('UPDATE users SET name=?,email=? WHERE id=?').run(name,email,req.user.id);audit(req.user,'profile',req.user.id,'update',JSON.stringify({name,email}));const u=db.prepare('SELECT id,name,email,role,business_unit_id FROM users WHERE id=?').get(req.user.id);res.json({user:u});});
app.put('/api/me/password',auth,(req,res)=>{const current=String(req.body.current_password||''),next=String(req.body.new_password||'');const u=db.prepare('SELECT password_hash FROM users WHERE id=?').get(req.user.id);if(!bcrypt.compareSync(current,u.password_hash))return res.status(400).json({error:'Current password is incorrect'});if(next.length<8)return res.status(400).json({error:'New password must be at least 8 characters'});db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(bcrypt.hashSync(next,12),req.user.id);audit(req.user,'profile',req.user.id,'password_change');res.json({ok:true});});
app.get('/api/context',auth,(req,res)=>{const units=req.user.role==='CEO / Owner'?db.prepare("SELECT id,name,status FROM business_units WHERE status!='Archived' ORDER BY name").all():db.prepare("SELECT id,name,status FROM business_units WHERE id=?").all(req.user.business_unit_id||0);res.json({units,selected_business_unit_id:req.selected_business_unit_id});});


app.get('/api/dashboard',auth,allow('dashboard'),(req,res)=>{
  try {
    const scope=unitScope(req,'business_unit_id');
    const suffix=scope.sql;
    const args=scope.args;
    const rev=db.prepare(`SELECT COALESCE(SUM(amount),0) v FROM finance_entries WHERE type='Revenue'${suffix}`).get(...args).v;
    const exp=db.prepare(`SELECT COALESCE(SUM(amount),0) v FROM finance_entries WHERE type='Expense'${suffix}`).get(...args).v;
    const sales=db.prepare(`SELECT COALESCE(SUM(total),0) v FROM sales WHERE status='Completed'${suffix}`).get(...args).v;
    const gp=db.prepare(`SELECT COALESCE(SUM(gross_profit),0) v FROM sales WHERE status='Completed'${suffix}`).get(...args).v;
    const pending=db.prepare(`SELECT COUNT(*) c FROM approvals WHERE status='Pending'${suffix}`).get(...args).c;
    const overdue=db.prepare(`SELECT COUNT(*) c FROM tasks WHERE status NOT IN ('Completed','Cancelled') AND due_date IS NOT NULL AND date(due_date)<date('now')${suffix}`).get(...args).c;
    const low=db.prepare(`SELECT COUNT(*) c FROM products WHERE active=1 AND item_type='PRODUCT' AND current_stock<=reorder_level${suffix}`).get(...args).c;
    const unread=db.prepare('SELECT COUNT(*) c FROM notifications WHERE (user_id IS NULL OR user_id=?) AND read_at IS NULL').get(req.user.id).c;
    const units=db.prepare(`SELECT b.id,b.name,b.status,
      COALESCE((SELECT SUM(total) FROM sales s WHERE s.business_unit_id=b.id AND s.status='Completed'),0) sales,
      COALESCE((SELECT SUM(gross_profit) FROM sales s WHERE s.business_unit_id=b.id AND s.status='Completed'),0) gross_profit,
      COALESCE((SELECT SUM(amount) FROM finance_entries f WHERE f.business_unit_id=b.id AND f.type='Expense'),0) expenses,
      COALESCE((SELECT SUM(p.current_stock*p.cost_price) FROM products p WHERE p.business_unit_id=b.id AND p.active=1),0) inventory_value
      FROM business_units b WHERE b.status!='Archived' ORDER BY b.name`).all();
    res.json({revenue:rev,expenses:exp,net:rev-exp,sales,gross_profit:gp,pending,overdue,low,unread,units,selected_business_unit_id:req.selected_business_unit_id,scope:req.user.role==='CEO / Owner'?(req.selected_business_unit_id?'unit':'all'):'unit'});
  } catch(e) {
    console.error('Dashboard error:',e);
    res.status(500).json({error:'Dashboard data could not be loaded: '+e.message});
  }
});
app.get('/api/dashboard/timeseries',auth,allow('dashboard'),(req,res)=>{const sc=unitScope(req,'business_unit_id');const rows=db.prepare(`SELECT date(created_at) d,COALESCE(SUM(total),0)sales,COALESCE(SUM(gross_profit),0)profit FROM sales WHERE status='Completed' AND date(created_at)>=date('now','-29 days')${sc.sql} GROUP BY date(created_at) ORDER BY d`).all(...sc.args);res.json(rows);});

app.get('/api/business-units',auth,(req,res)=>{let q=`SELECT b.*,u.name manager_name FROM business_units b LEFT JOIN users u ON u.id=b.manager_id WHERE b.status!=\'Archived\'`;const sc=unitScope(req,'b.id');q+=sc.sql.replace(' AND b.id=?',' AND b.id=?');res.json(db.prepare(q+' ORDER BY b.name').all(...sc.args));});
app.post('/api/business-units',auth,(req,res,next)=>req.user.role==='CEO / Owner'?next():res.status(403).json({error:'Only CEO can manage business units'}),(req,res)=>{if(!req.body.name)return res.status(400).json({error:'Business name is required'});try{const r=db.prepare('INSERT INTO business_units(name,manager_id,status,notes) VALUES(?,?,?,?)').run(req.body.name,req.body.manager_id||null,req.body.status||'Active',req.body.notes||'');audit(req.user,'business_unit',r.lastInsertRowid,'create',req.body.name);res.json({id:r.lastInsertRowid});}catch(e){res.status(400).json({error:'Business unit already exists'});}});
app.put('/api/business-units/:id',auth,(req,res,next)=>req.user.role==='CEO / Owner'?next():res.status(403).json({error:'Only CEO can manage business units'}),(req,res)=>{db.prepare('UPDATE business_units SET name=COALESCE(?,name),manager_id=?,status=COALESCE(?,status),notes=COALESCE(?,notes) WHERE id=?').run(req.body.name||null,req.body.manager_id||null,req.body.status||null,req.body.notes||null,req.params.id);audit(req.user,'business_unit',req.params.id,'update',JSON.stringify(req.body));res.json({ok:true});});

app.delete('/api/business-units/:id',auth,(req,res,next)=>req.user.role==='CEO / Owner'?next():res.status(403).json({error:'Only CEO can manage business units'}),(req,res)=>{const b=db.prepare('SELECT * FROM business_units WHERE id=?').get(req.params.id);if(!b)return res.status(404).json({error:'Business unit not found'});const refs=db.prepare('SELECT COUNT(*) c FROM products WHERE business_unit_id=?').get(b.id).c+db.prepare('SELECT COUNT(*) c FROM sales WHERE business_unit_id=?').get(b.id).c+db.prepare('SELECT COUNT(*) c FROM finance_entries WHERE business_unit_id=?').get(b.id).c;if(refs>0)return res.status(400).json({error:'Business has historical records. Set it to Closed instead of deleting it.'});db.prepare('DELETE FROM business_units WHERE id=?').run(b.id);audit(req.user,'business_unit',b.id,'delete',b.name);res.json({ok:true});});

app.get('/api/users',auth,allow('staff'),(req,res)=>{let q=`SELECT u.id,u.name,u.email,u.role,u.business_unit_id,b.name business_unit,u.active,u.created_at FROM users u LEFT JOIN business_units b ON b.id=u.business_unit_id WHERE 1=1`;const sc=unitScope(req,'u.business_unit_id');q+=sc.sql;res.json(db.prepare(q+' ORDER BY u.name').all(...sc.args));});
app.post('/api/users',auth,allow('staff'),(req,res)=>{const {name,email,password,role,business_unit_id}=req.body;if(req.user.role!=='CEO / Owner' && !enforceUnit(req,business_unit_id))return res.status(403).json({error:'User must belong to your business unit'});if(!name||!email||!password||!role)return res.status(400).json({error:'Name, email, password and role are required'});try{const r=db.prepare('INSERT INTO users(name,email,password_hash,role,business_unit_id) VALUES(?,?,?,?,?)').run(name,email,bcrypt.hashSync(password,12),role,business_unit_id||null);notify(r.lastInsertRowid,'info','Welcome to Blue Ocean','Your account has been created.');audit(req.user,'user',r.lastInsertRowid,'create',email);res.json({id:r.lastInsertRowid});}catch(e){res.status(400).json({error:'Email already exists'});}});

app.put('/api/users/:id',auth,allow('staff'),(req,res)=>{const u=db.prepare('SELECT * FROM users WHERE id=?').get(req.params.id);if(!u)return res.status(404).json({error:'User not found'});if(req.user.role!=='CEO / Owner' && !enforceUnit(req,u.business_unit_id||0))return res.status(403).json({error:'You cannot manage another business unit user'});const nextBusiness=req.body.business_unit_id===undefined?u.business_unit_id:(req.body.business_unit_id===''?null:Number(req.body.business_unit_id));if(req.user.role!=='CEO / Owner' && !enforceUnit(req,nextBusiness||0))return res.status(403).json({error:'User must remain in your business unit'});db.prepare('UPDATE users SET name=?,email=?,role=?,business_unit_id=?,active=? WHERE id=?').run(req.body.name??u.name,req.body.email??u.email,req.body.role??u.role,nextBusiness,req.body.active===undefined?u.active:(req.body.active?1:0),u.id);if(req.body.password)db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(bcrypt.hashSync(req.body.password,12),u.id);audit(req.user,'user',u.id,req.body.active===0?'deactivate':req.body.active===1?'activate':'update',u.email);res.json({ok:true,business_unit_id:nextBusiness,active:req.body.active===undefined?u.active:(req.body.active?1:0)});});
app.delete('/api/users/:id',auth,allow('staff'),(req,res)=>{if(req.user.role!=='CEO / Owner')return res.status(403).json({error:'Only CEO / Owner can permanently delete a user profile'});if(Number(req.params.id)===Number(req.user.id))return res.status(400).json({error:'You cannot delete your own account'});const u=db.prepare('SELECT * FROM users WHERE id=?').get(req.params.id);if(!u)return res.status(404).json({error:'User not found'});db.transaction(()=>{db.prepare('UPDATE business_units SET manager_id=NULL WHERE manager_id=?').run(u.id);db.prepare('DELETE FROM notifications WHERE user_id=?').run(u.id);db.prepare('DELETE FROM audit_log WHERE user_id=?').run(u.id);db.prepare('DELETE FROM users WHERE id=?').run(u.id)})();res.json({ok:true});});

app.get('/api/tasks',auth,allow('tasks'),(req,res)=>{let q=`SELECT t.*,u.name owner,b.name business_unit FROM tasks t JOIN users u ON u.id=t.owner_id LEFT JOIN business_units b ON b.id=t.business_unit_id WHERE 1=1`;const s=unitScope(req,'t.business_unit_id');q+=s.sql;const args=[...s.args];if(req.user.role==='Staff Member'){q+=' AND t.owner_id=?';args.push(req.user.id);}res.json(db.prepare(q+' ORDER BY CASE t.priority WHEN \'Critical\' THEN 1 WHEN \'High\' THEN 2 WHEN \'Normal\' THEN 3 ELSE 4 END,t.due_date').all(...args));});
app.post('/api/tasks',auth,allow('tasks'),(req,res)=>{const {title,owner_id,business_unit_id,priority='Normal',due_date,expected_result='',recurring='None'}=req.body;if(!business_unit_id||!enforceUnit(req,business_unit_id))return res.status(403).json({error:'Task must belong to the current business unit'});if(!title||!owner_id)return res.status(400).json({error:'Task title and owner are required'});const r=db.prepare('INSERT INTO tasks(title,owner_id,business_unit_id,priority,due_date,expected_result,recurring,created_by) VALUES(?,?,?,?,?,?,?,?)').run(title,owner_id,business_unit_id||null,priority,due_date||null,expected_result,recurring,req.user.id);notify(owner_id,'info','New task assigned',title);audit(req.user,'task',r.lastInsertRowid,'create',title);res.json({id:r.lastInsertRowid});});
app.put('/api/tasks/:id',auth,allow('tasks'),(req,res)=>{const t=db.prepare('SELECT * FROM tasks WHERE id=?').get(req.params.id);if(t && !enforceUnit(req,t.business_unit_id||0))return res.status(403).json({error:'You cannot access another business unit task'});if(!t)return res.status(404).json({error:'Task not found'});if(req.user.role==='Staff Member'&&t.owner_id!==req.user.id)return res.status(403).json({error:'Not your task'});db.prepare('UPDATE tasks SET title=COALESCE(?,title),owner_id=?,business_unit_id=?,status=COALESCE(?,status),priority=COALESCE(?,priority),due_date=COALESCE(?,due_date),expected_result=COALESCE(?,expected_result) WHERE id=?').run(req.body.title??t.title,req.body.owner_id||null,req.body.business_unit_id||null,req.body.status||null,req.body.priority||null,req.body.due_date||null,req.body.expected_result||null,t.id);db.prepare('INSERT INTO task_history(task_id,user_id,action,note) VALUES(?,?,?,?)').run(t.id,req.user.id,'update',JSON.stringify(req.body));audit(req.user,'task',t.id,'update',JSON.stringify(req.body));res.json({ok:true});});
app.delete('/api/tasks/:id',auth,allow('tasks'),(req,res)=>{const t=db.prepare('SELECT * FROM tasks WHERE id=?').get(req.params.id);if(t && !enforceUnit(req,t.business_unit_id||0))return res.status(403).json({error:'You cannot access another business unit task'});if(!t)return res.status(404).json({error:'Task not found'});if(req.user.role==='Staff Member'&&t.owner_id!==req.user.id)return res.status(403).json({error:'Not your task'});db.prepare('DELETE FROM tasks WHERE id=?').run(t.id);audit(req.user,'task',t.id,'delete',t.title);res.json({ok:true});});

app.get('/api/products',auth,allow('inventory','sales','pos'),(req,res)=>{let q=`SELECT p.*,b.name business_unit FROM products p JOIN business_units b ON b.id=p.business_unit_id WHERE p.active=1`;const s=unitScope(req,'p.business_unit_id');q+=s.sql;res.json(db.prepare(q+' ORDER BY b.name,p.name').all(...s.args));});
app.post('/api/products',auth,allow('inventory'),(req,res)=>{const {business_unit_id,sku,name,category='General',supplier='',item_type='PRODUCT',unit='pcs',opening_stock=0,reorder_level=0,cost_price=0,selling_price=0,tax_rate=0}=req.body;if(!business_unit_id||!enforceUnit(req,business_unit_id)||!sku||!name)return res.status(400).json({error:'Business, SKU and name are required'});try{const r=db.prepare('INSERT INTO products(business_unit_id,sku,name,category,supplier,item_type,unit,opening_stock,current_stock,reorder_level,cost_price,selling_price,tax_rate) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)').run(business_unit_id,sku,name,category,supplier,item_type,unit,num(opening_stock),num(opening_stock),num(reorder_level),num(cost_price),num(selling_price),num(tax_rate));if(num(opening_stock))db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,user_id) VALUES(?,?,?,?,?,?)').run(r.lastInsertRowid,'Opening',num(opening_stock),num(cost_price),'Opening stock',req.user.id);audit(req.user,'product',r.lastInsertRowid,'create',name);res.json({id:r.lastInsertRowid});}catch(e){res.status(400).json({error:'SKU already exists in this business'});}});
app.put('/api/products/:id',auth,allow('inventory'),(req,res)=>{const p=db.prepare('SELECT * FROM products WHERE id=?').get(req.params.id);if(p && !enforceUnit(req,p.business_unit_id))return res.status(403).json({error:'You cannot access another business unit product'});if(!p)return res.status(404).json({error:'Product/service not found'});db.prepare(`UPDATE products SET sku=?,name=?,category=?,supplier=?,item_type=?,unit=?,reorder_level=?,cost_price=?,selling_price=?,tax_rate=?,active=? WHERE id=?`).run(req.body.sku??p.sku,req.body.name??p.name,req.body.category??p.category,req.body.supplier??p.supplier,req.body.item_type??p.item_type,req.body.unit??p.unit,num(req.body.reorder_level??p.reorder_level),num(req.body.cost_price??p.cost_price),num(req.body.selling_price??p.selling_price),num(req.body.tax_rate??p.tax_rate),req.body.active===undefined?p.active:(req.body.active?1:0),p.id);audit(req.user,'product',p.id,'update',JSON.stringify(req.body));res.json({ok:true});});
app.delete('/api/products/:id',auth,allow('inventory'),(req,res)=>{const p=db.prepare('SELECT * FROM products WHERE id=?').get(req.params.id);if(p && !enforceUnit(req,p.business_unit_id))return res.status(403).json({error:'You cannot access another business unit product'});if(!p)return res.status(404).json({error:'Product/service not found'});db.prepare('UPDATE products SET active=0 WHERE id=?').run(p.id);audit(req.user,'product',p.id,'archive',p.name);res.json({ok:true});});

app.post('/api/inventory/move',auth,allow('inventory'),(req,res)=>{const p=db.prepare('SELECT * FROM products WHERE id=?').get(req.body.product_id);if(p && !enforceUnit(req,p.business_unit_id))return res.status(403).json({error:'You cannot access another business unit inventory'});if(!p)return res.status(404).json({error:'Product not found'});let q=num(req.body.quantity);const type=req.body.type||'ADD';if(q<=0)return res.status(400).json({error:'Quantity must be greater than zero'});if(type==='REMOVE'||type==='WASTE'||type==='SALE'){if(p.current_stock<q)return res.status(400).json({error:'Insufficient stock'});q=-q;}db.prepare('UPDATE products SET current_stock=current_stock+? WHERE id=?').run(q,p.id);db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,user_id) VALUES(?,?,?,?,?,?)').run(p.id,type,Math.abs(q),p.cost_price,req.body.reason||'',req.user.id);audit(req.user,'inventory',p.id,type,`${Math.abs(q)}`);res.json({ok:true});});
app.get('/api/inventory/summary',auth,allow('inventory','dashboard'),(req,res)=>{const sc=unitScope(req,'p.business_unit_id');const products=db.prepare(`SELECT COUNT(*) items,COALESCE(SUM(p.current_stock*p.cost_price),0) value,COALESCE(SUM(CASE WHEN p.current_stock<=p.reorder_level AND p.reorder_level>0 THEN 1 ELSE 0 END),0) low,COALESCE(SUM(CASE WHEN p.current_stock<=0 THEN 1 ELSE 0 END),0) out FROM products p WHERE p.active=1 AND p.item_type='PRODUCT'${sc.sql}`).get(...sc.args);const rows=db.prepare(`SELECT p.id,p.name,p.sku,b.name business_unit,p.unit,p.current_stock,p.reorder_level,p.cost_price,p.selling_price FROM products p JOIN business_units b ON b.id=p.business_unit_id WHERE p.active=1${sc.sql} ORDER BY b.name,p.name`).all(...sc.args);res.json({products,rows});});
app.get('/api/inventory/movements',auth,allow('inventory'),(req,res)=>{let q=`SELECT sm.*,p.name product,p.sku,b.name business_unit,u.name user_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN business_units b ON b.id=p.business_unit_id LEFT JOIN users u ON u.id=sm.user_id WHERE 1=1`;const sc=unitScope(req,'p.business_unit_id');q+=sc.sql;res.json(db.prepare(q+' ORDER BY sm.created_at DESC LIMIT 300').all(...sc.args));});

function createSale(req,res,restaurant=false){const b=restaurant?db.prepare('SELECT id FROM business_units WHERE name=\'MIMI Resturant\'').get()?.id:req.body.business_unit_id;if(!b || !enforceUnit(req,b))return res.status(403).json({error:'Sale must belong to the current business unit'});const items=Array.isArray(req.body.items)?req.body.items:[];if(!items.length)return res.status(400).json({error:'Add at least one item'});let subtotal=0,cost=0,tax=0,clean=[];for(const it of items){const p=db.prepare('SELECT * FROM products WHERE id=? AND business_unit_id=?').get(it.product_id,b);if(!p)return res.status(400).json({error:'Invalid item'});const qty=num(it.quantity);if(qty<=0)return res.status(400).json({error:'Invalid quantity'});if(p.item_type==='PRODUCT'&&p.current_stock<qty)return res.status(400).json({error:`Insufficient stock: ${p.name}`});const price=num(it.unit_price||p.selling_price),line=qty*price,tc=qty*p.cost_price,tt=line*(num(p.tax_rate)/100);subtotal+=line;cost+=tc;tax+=tt;clean.push({p,qty,price,line,tt});}const discount=num(req.body.discount),total=Math.max(0,subtotal-discount+tax),gp=total-cost;const invoice=nextNo(restaurant?'MIMI':'INV','sales','id');const sale=db.prepare('INSERT INTO sales(business_unit_id,invoice_no,customer_id,customer_name,order_type,payment_method,subtotal,discount,tax,total,cost_total,gross_profit,receipt_file,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(b,invoice,req.body.customer_id||null,req.body.customer_name||'',req.body.order_type||'Sale',req.body.payment_method||'Cash',subtotal,discount,tax,total,cost,gp,req.body.receipt_file||'',req.body.notes||'',req.user.id);const add=db.prepare('INSERT INTO sale_items(sale_id,product_id,item_type,item_name,quantity,unit_price,unit_cost,tax_rate,line_total) VALUES(?,?,?,?,?,?,?,?,?)');const move=db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,reference_type,reference_id,user_id) VALUES(?,?,?,?,?,?,?,?)');for(const x of clean){add.run(sale.lastInsertRowid,x.p.id,x.p.item_type,x.p.name,x.qty,x.price,x.p.cost_price,x.p.tax_rate,x.line);if(x.p.item_type==='PRODUCT'){db.prepare('UPDATE products SET current_stock=current_stock-? WHERE id=?').run(x.qty,x.p.id);move.run(x.p.id,'SALE',x.qty,x.p.cost_price,invoice,'SALE',sale.lastInsertRowid,req.user.id);}}db.prepare('INSERT INTO finance_entries(business_unit_id,type,category,amount,description,status,payment_method,reference,created_by) VALUES(?,?,?,?,?,?,?,?,?)').run(b,'Revenue','Sales',total,`${restaurant?'Restaurant POS':'Sale'} ${invoice}`,'Recorded',req.body.payment_method||'Cash',invoice,req.user.id);audit(req.user,'sale',sale.lastInsertRowid,'create',invoice);res.json({id:sale.lastInsertRowid,invoice,total,gross_profit:gp});}
app.post('/api/sales',auth,allow('sales','pos'),(req,res)=>createSale(req,res,false));
app.get('/api/sales/:id',auth,allow('sales','pos'),(req,res)=>{const s=db.prepare(`SELECT s.*,b.name business_unit FROM sales s JOIN business_units b ON b.id=s.business_unit_id WHERE s.id=?`).get(req.params.id);if(s && !enforceUnit(req,s.business_unit_id))return res.status(403).json({error:'You cannot access another business unit sale'});if(!s)return res.status(404).json({error:'Sale not found'});s.items=db.prepare('SELECT * FROM sale_items WHERE sale_id=? ORDER BY id').all(s.id);res.json(s);});

app.put('/api/sales/:id/void',auth,allow('sales','finance'),(req,res)=>{const s=db.prepare('SELECT * FROM sales WHERE id=?').get(req.params.id);if(s && !enforceUnit(req,s.business_unit_id))return res.status(403).json({error:'You cannot access another business unit sale'});if(!s)return res.status(404).json({error:'Sale not found'});if(s.status==='Voided')return res.json({ok:true});db.prepare("UPDATE sales SET status='Voided' WHERE id=?").run(s.id);db.prepare("UPDATE finance_entries SET status='Voided' WHERE reference=?").run(s.invoice_no);audit(req.user,'sale',s.id,'void',s.invoice_no);res.json({ok:true});});

app.get('/api/sales',auth,allow('sales','pos'),(req,res)=>{let q=`SELECT s.*,b.name business_unit,u.name created_by_name FROM sales s JOIN business_units b ON b.id=s.business_unit_id LEFT JOIN users u ON u.id=s.created_by WHERE 1=1`;const s=unitScope(req,'s.business_unit_id');q+=s.sql;res.json(db.prepare(q+' ORDER BY s.created_at DESC LIMIT 500').all(...s.args));});
app.post('/api/purchases',auth,allow('purchases','inventory'),upload.single('attachment'),(req,res)=>{const b=req.body.business_unit_id,items=JSON.parse(req.body.items||'[]');if(!b||!enforceUnit(req,b)||!items.length)return res.status(400).json({error:'Business and items are required'});let total=0,clean=[];for(const it of items){const p=db.prepare('SELECT * FROM products WHERE id=? AND business_unit_id=?').get(it.product_id,b);if(!p)return res.status(400).json({error:'Invalid product'});const q=num(it.quantity),c=num(it.unit_cost||p.cost_price),line=q*c;total+=line;clean.push({p,q,c,line});}const no=nextNo('PO','purchases','id'),file=req.file?.filename||'';const r=db.prepare('INSERT INTO purchases(business_unit_id,purchase_no,supplier_name,payment_method,subtotal,total,attachment_file,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)').run(b,no,req.body.supplier_name||'',req.body.payment_method||'Cash',total,total,file,req.body.notes||'',req.user.id);const add=db.prepare('INSERT INTO purchase_items(purchase_id,product_id,item_name,quantity,unit_cost,line_total) VALUES(?,?,?,?,?,?)');for(const x of clean){add.run(r.lastInsertRowid,x.p.id,x.p.name,x.q,x.c,x.line);if(x.p.item_type==='PRODUCT'){db.prepare('UPDATE products SET current_stock=current_stock+?,cost_price=? WHERE id=?').run(x.q,x.c,x.p.id);db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,reference_type,reference_id,user_id) VALUES(?,?,?,?,?,?,?,?)').run(x.p.id,'PURCHASE',x.q,x.c,no,'PURCHASE',r.lastInsertRowid,req.user.id);}}db.prepare('INSERT INTO finance_entries(business_unit_id,type,category,amount,description,payment_method,reference,receipt_file,created_by) VALUES(?,?,?,?,?,?,?,?,?)').run(b,'Expense','Purchases',total,`Purchase ${no}`,req.body.payment_method||'Cash',no,file,req.user.id);audit(req.user,'purchase',r.lastInsertRowid,'create',no);res.json({id:r.lastInsertRowid,purchase_no:no,total});});
app.put('/api/purchases/:id',auth,allow('purchases','inventory'),(req,res)=>{const p=db.prepare('SELECT * FROM purchases WHERE id=?').get(req.params.id);if(p && !enforceUnit(req,p.business_unit_id))return res.status(403).json({error:'You cannot access another business unit purchase'});if(!p)return res.status(404).json({error:'Purchase not found'});db.prepare('UPDATE purchases SET supplier_name=?,payment_method=?,notes=?,status=? WHERE id=?').run(req.body.supplier_name??p.supplier_name,req.body.payment_method??p.payment_method,req.body.notes??p.notes,req.body.status??p.status,p.id);audit(req.user,'purchase',p.id,'update',JSON.stringify(req.body));res.json({ok:true});});
app.delete('/api/purchases/:id',auth,allow('purchases','inventory'),(req,res)=>{const p=db.prepare('SELECT * FROM purchases WHERE id=?').get(req.params.id);if(p && !enforceUnit(req,p.business_unit_id))return res.status(403).json({error:'You cannot access another business unit purchase'});if(!p)return res.status(404).json({error:'Purchase not found'});db.prepare("UPDATE purchases SET status='Voided' WHERE id=?").run(p.id);audit(req.user,'purchase',p.id,'void',p.purchase_no);res.json({ok:true});});

