app.get('/api/finance',auth,allow('finance','dashboard'),(req,res)=>{let q=`SELECT f.*,b.name business_unit,u.name created_by_name,v.name verified_by_name,(SELECT COUNT(*) FROM finance_attachments fa WHERE fa.finance_entry_id=f.id) attachment_count FROM finance_entries f JOIN business_units b ON b.id=f.business_unit_id LEFT JOIN users u ON u.id=f.created_by LEFT JOIN users v ON v.id=f.verified_by WHERE 1=1`;const s=unitScope(req,'f.business_unit_id');q+=s.sql;res.json(db.prepare(q+' ORDER BY f.created_at DESC LIMIT 500').all(...s.args));});
