app.post('/api/finance',auth,allow('finance'),upload.array('attachments',30),(req,res)=>{const b=req.body.business_unit_id;if(!b||!enforceUnit(req,b))return res.status(403).json({error:'Finance entry must belong to the current business unit'});const r=db.prepare('INSERT INTO finance_entries(business_unit_id,type,category,amount,description,due_date,status,receipt_file,payment_method,reference,created_by,verification_status,source_type,source_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(b,req.body.type||'Expense',req.body.category||'General',num(req.body.amount),req.body.description||'',req.body.due_date||null,req.body.status||'Recorded',req.files?.[0]?.filename||'',req.body.payment_method||'',req.body.reference||'',req.user.id,'Pending Verification',req.body.source_type||'Manual',req.body.source_id?Number(req.body.source_id):null);const ins=db.prepare('INSERT INTO finance_attachments(finance_entry_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?)');for(const f of (req.files||[]))ins.run(r.lastInsertRowid,req.body.description||'Finance attachment',f.originalname,'/uploads/'+f.filename,f.mimetype,f.size,req.user.id);audit(req.user,'finance',r.lastInsertRowid,'create',req.body.description||'');res.json({id:r.lastInsertRowid,attachment_count:(req.files||[]).length});});
app.put('/api/finance/:id/verify',auth,(req,res,next)=>{if(!['CEO / Owner','Finance / Admin'].includes(req.user.role))return res.status(403).json({error:'Only Finance Manager or CEO can verify finance entries'});next()},(req,res)=>{const f=db.prepare('SELECT * FROM finance_entries WHERE id=?').get(req.params.id);if(!f)return res.status(404).json({error:'Finance entry not found'});if(!enforceUnit(req,f.business_unit_id))return res.status(403).json({error:'You cannot verify another business unit finance entry'});const st=req.body.verification_status;if(!['Verified / Correct','Rejected / Incorrect','Pending Verification'].includes(st))return res.status(400).json({error:'Invalid verification status'});db.prepare('UPDATE finance_entries SET verification_status=?,verified_by=?,verified_at=CURRENT_TIMESTAMP,verification_note=? WHERE id=?').run(st,req.user.id,req.body.verification_note||'',f.id);audit(req.user,'finance',f.id,'verify',st);res.json({ok:true});});
app.get('/api/pnl',auth,allow('finance','dashboard'),(req,res)=>{let units=db.prepare('SELECT id,name FROM business_units WHERE status!=\'Archived\' ORDER BY name').all();if(req.selected_business_unit_id)units=units.filter(x=>Number(x.id)===Number(req.selected_business_unit_id));if(req.user.role!=='CEO / Owner')units=units.filter(x=>Number(x.id)===Number(req.user.business_unit_id));const data=units.map(b=>{const sales=db.prepare('SELECT COALESCE(SUM(total),0)v,COALESCE(SUM(cost_total),0)c,COALESCE(SUM(gross_profit),0)g FROM sales WHERE business_unit_id=? AND status=\'Completed\'').get(b.id);const exp=db.prepare('SELECT COALESCE(SUM(amount),0)v FROM finance_entries WHERE business_unit_id=? AND type=\'Expense\' AND category NOT IN (\'Purchases\')').get(b.id).v;const purchases=db.prepare('SELECT COALESCE(SUM(amount),0)v FROM finance_entries WHERE business_unit_id=? AND type=\'Expense\' AND category=\'Purchases\'').get(b.id).v;return{...b,sales:sales.v,cogs:sales.c,gross_profit:sales.g,operating_expense:exp,purchases,net_profit:sales.g-exp};});res.json(data);});

