app.get('/api/restaurant/tables',auth,allow('restaurant','pos'),(req,res)=>{const id=db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id;if(id&&!enforceUnit(req,id))return res.status(403).json({error:'Select MIMI Resturant to use restaurant functions'});res.json(id?db.prepare('SELECT * FROM restaurant_tables WHERE business_unit_id=? ORDER BY id').all(id):[]);});
