app.delete('/api/restaurant/tables/:id',auth,allow('restaurant'),(req,res)=>{const t=db.prepare('SELECT * FROM restaurant_tables WHERE id=?').get(req.params.id);if(t && !enforceUnit(req,t.business_unit_id))return res.status(403).json({error:'You cannot access another business unit restaurant table'});if(!t)return res.status(404).json({error:'Table not found'});if(t.status==='Busy'){return res.status(400).json({error:'Busy table cannot be deleted while it has an active order'});}const open=db.prepare("SELECT 1 FROM restaurant_orders WHERE table_id=? AND status='Open' LIMIT 1").get(t.id);if(open)return res.status(400).json({error:'Table has an open order and cannot be deleted'});db.prepare('DELETE FROM restaurant_tables WHERE id=?').run(t.id);res.json({ok:true});});

app.get('/api/restaurant/orders',auth,allow('restaurant','pos'),(req,res)=>{const b=db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id;if(!b||!enforceUnit(req,b))return res.status(403).json({error:'Select MIMI Resturant to use restaurant functions'});res.json(db.prepare(`SELECT o.*,t.name table_name FROM restaurant_orders o LEFT JOIN restaurant_tables t ON t.id=o.table_id WHERE o.business_unit_id=? ORDER BY o.created_at DESC LIMIT 300`).all(b));});
app.post('/api/restaurant/orders',auth,allow('restaurant','pos'),(req,res)=>{const b=db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id;if(!b)return res.status(404).json({error:'MIMI Resturant not found'});if(!enforceUnit(req,b))return res.status(403).json({error:'Select MIMI Resturant to use restaurant functions'});const items=Array.isArray(req.body.items)?req.body.items:[];if(!items.length)return res.status(400).json({error:'Add items'});const orderNo=nextNo('MIMI','restaurant_orders','id');const tableId=req.body.table_id||null;if((req.body.order_type||'Dine-in')==='Dine-in'&&!tableId)return res.status(400).json({error:'Select an available table for dine-in'});if((req.body.order_type||'Dine-in')==='Dine-in'&&tableId){const t=db.prepare('SELECT * FROM restaurant_tables WHERE id=? AND business_unit_id=?').get(tableId,b);if(!t)return res.status(400).json({error:'Invalid table'});if(t.status!=='Available')return res.status(400).json({error:'Selected table is not available'});}const r=db.prepare('INSERT INTO restaurant_orders(business_unit_id,table_id,order_no,order_type,customer_name,status,created_by) VALUES(?,?,?,?,?,?,?)').run(b,tableId,orderNo,req.body.order_type||'Dine-in',req.body.customer_name||'','Open',req.user.id);if(tableId)db.prepare("UPDATE restaurant_tables SET status='Busy' WHERE id=?").run(tableId);const add=db.prepare('INSERT INTO restaurant_order_items(order_id,product_id,item_name,quantity,unit_price,unit_cost,line_total,kitchen_status,notes) VALUES(?,?,?,?,?,?,?,?,?)');for(const it of items){const p=db.prepare('SELECT * FROM products WHERE id=? AND business_unit_id=?').get(it.product_id,b);if(!p)return res.status(400).json({error:'Invalid menu item'});const q=num(it.quantity);const price=it.unit_price===undefined?p.selling_price:num(it.unit_price);if(price<0)return res.status(400).json({error:'Invalid price'});add.run(r.lastInsertRowid,p.id,p.name,q,price,p.cost_price,q*price,'Pending',it.notes||'');}res.json({id:r.lastInsertRowid,order_no:orderNo});});
app.post('/api/restaurant/orders/:id/cancel',auth,allow('restaurant','pos'),(req,res)=>{const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});if(!enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'Wrong business unit'});if(o.status!=='Open')return res.status(400).json({error:'Only open orders can be cancelled'});const reason=(req.body?.reason||'Cancelled by user').trim();db.prepare("UPDATE restaurant_orders SET status='Cancelled',closed_at=CURRENT_TIMESTAMP WHERE id=?").run(o.id);if(o.table_id)db.prepare("UPDATE restaurant_tables SET status='Available' WHERE id=? AND business_unit_id=?").run(o.table_id,o.business_unit_id);audit(req.user,'restaurant_order',o.id,'cancel',JSON.stringify({order_no:o.order_no,reason}));res.json({ok:true,status:'Cancelled',order_no:o.order_no});});
app.delete('/api/restaurant/orders/:id',auth,allow('restaurant','pos'),(req,res)=>{const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});if(!enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'Wrong business unit'});if(o.status!=='Open')return res.status(400).json({error:'Only open orders can be deleted'});const reason=(req.body?.reason||'Deleted/cancelled by user').trim();db.prepare("UPDATE restaurant_orders SET status='Cancelled',closed_at=CURRENT_TIMESTAMP WHERE id=?").run(o.id);if(o.table_id)db.prepare("UPDATE restaurant_tables SET status='Available' WHERE id=? AND business_unit_id=?").run(o.table_id,o.business_unit_id);audit(req.user,'restaurant_order',o.id,'delete',JSON.stringify({order_no:o.order_no,reason}));res.json({ok:true,status:'Cancelled',order_no:o.order_no});});
app.put('/api/restaurant/orders/:id/kitchen',auth,allow('restaurant'),(req,res)=>{db.prepare('UPDATE restaurant_order_items SET kitchen_status=? WHERE id=?').run(req.body.status||'Preparing',req.body.item_id);res.json({ok:true});});
app.post('/api/restaurant/orders/:id/save',auth,allow('restaurant','pos'),(req,res)=>{const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});if(!enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'Wrong business unit'});if(o.status!=='Open')return res.status(400).json({error:'Only open orders can be saved'});const items=db.prepare('SELECT * FROM restaurant_order_items WHERE order_id=?').all(o.id);const subtotal=items.reduce((a,x)=>a+num(x.line_total),0);db.prepare('UPDATE restaurant_orders SET subtotal=?,total=? WHERE id=?').run(subtotal,subtotal,o.id);audit(req.user,'restaurant_order',o.id,'save');res.json({ok:true,subtotal,total:subtotal});});
app.post('/api/restaurant/orders/:id/close',auth,allow('restaurant','pos'),(req,res)=>{const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);if(o && !enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'You cannot access another business unit restaurant order'});if(!o)return res.status(404).json({error:'Order not found'});const items=db.prepare('SELECT * FROM restaurant_order_items WHERE order_id=?').all(o.id);createSale({body:{business_unit_id:o.business_unit_id,customer_name:o.customer_name,order_type:o.order_type,payment_method:req.body.payment_method||'Cash',items:items.map(x=>({product_id:x.product_id,quantity:x.quantity,unit_price:x.unit_price})),discount:req.body.discount||0},user:req.user,protocol:'',get:()=>''}, {status:()=>({json:x=>res.status(400).json(x)}),json:x=>{if(x.error)return res.status(400).json(x);db.prepare('UPDATE restaurant_orders SET status=\'Closed\',payment_method=?,subtotal=?,discount=?,tax=?,total=?,sale_id=?,closed_at=CURRENT_TIMESTAMP WHERE id=?').run(req.body.payment_method||'Cash',x.total,0,0,x.total,x.id,o.id);const t=db.prepare('SELECT table_id FROM restaurant_orders WHERE id=?').get(o.id);if(t.table_id)db.prepare('UPDATE restaurant_tables SET status=\'Available\' WHERE id=?').run(t.table_id);res.json(x);}} ,true);});
app.post('/api/restaurant/waste',auth,allow('restaurant','inventory'),(req,res)=>{const p=db.prepare('SELECT * FROM products WHERE id=?').get(req.body.product_id);if(p && !enforceUnit(req,p.business_unit_id))return res.status(403).json({error:'You cannot access another business unit inventory'});if(!p)return res.status(404).json({error:'Product not found'});const q=num(req.body.quantity);if(p.current_stock<q)return res.status(400).json({error:'Insufficient stock'});db.prepare('UPDATE products SET current_stock=current_stock-? WHERE id=?').run(q,p.id);const r=db.prepare('INSERT INTO restaurant_waste(business_unit_id,product_id,quantity,reason,estimated_cost,created_by) VALUES(?,?,?,?,?,?)').run(p.business_unit_id,p.id,q,req.body.reason||'',q*p.cost_price,req.user.id);db.prepare('INSERT INTO stock_movements(product_id,type,quantity,unit_cost,reason,user_id) VALUES(?,?,?,?,?,?)').run(p.id,'WASTE',q,p.cost_price,req.body.reason||'',req.user.id);res.json({id:r.lastInsertRowid});});
app.post('/api/restaurant/closing',auth,allow('restaurant','finance'),(req,res)=>{const b=db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id;if(!b||!enforceUnit(req,b))return res.status(403).json({error:'Select MIMI Resturant to use restaurant functions'});const d=req.body.business_date||new Date().toISOString().slice(0,10);const sales=db.prepare(`SELECT COALESCE(SUM(CASE WHEN payment_method='Cash' THEN total ELSE 0 END),0)cash,COALESCE(SUM(CASE WHEN payment_method IN ('Card','Bank') THEN total ELSE 0 END),0)card,COALESCE(SUM(CASE WHEN payment_method NOT IN ('Cash','Card','Bank') THEN total ELSE 0 END),0)other FROM sales WHERE business_unit_id=? AND date(created_at)=?`).get(b,d);const variance=num(req.body.cash_counted)-sales.cash;const r=db.prepare(`INSERT INTO restaurant_closings(business_unit_id,business_date,cash_sales,card_sales,other_sales,cash_counted,variance,notes,closed_by) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(business_unit_id,business_date) DO UPDATE SET cash_sales=excluded.cash_sales,card_sales=excluded.card_sales,other_sales=excluded.other_sales,cash_counted=excluded.cash_counted,variance=excluded.variance,notes=excluded.notes,closed_by=excluded.closed_by`).run(b,d,sales.cash,sales.card,sales.other,num(req.body.cash_counted),variance,req.body.notes||'',req.user.id);res.json({id:r.lastInsertRowid,...sales,variance});});


// MIMI Restaurant upgraded modules: menu, stock, weekly menu, buffet, open-order editing and table-aware dine-in.
function mimiId(){return db.prepare("SELECT id FROM business_units WHERE name='MIMI Resturant'").get()?.id;}
function mimiGuard(req,res){const b=mimiId();if(!b)return null;if(!enforceUnit(req,b)){res.status(403).json({error:'Select MIMI Resturant to use restaurant functions'});return null;}return b;}
function syncBuffetProduct(buffet){const sku=`MIMI-BUFFET-${buffet.id}`;let p=db.prepare('SELECT * FROM products WHERE business_unit_id=? AND sku=?').get(buffet.business_unit_id,sku);const active=buffet.status==='Published';if(!p){const r=db.prepare('INSERT INTO products(business_unit_id,sku,name,category,supplier,item_type,unit,opening_stock,current_stock,reorder_level,cost_price,selling_price,tax_rate,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(buffet.business_unit_id,sku,`Buffet: ${buffet.name}`,'Buffet','MIMI','SERVICE','buffet',0,0,0,0,num(buffet.price),0,active?1:0);p=db.prepare('SELECT * FROM products WHERE id=?').get(r.lastInsertRowid);}else{db.prepare('UPDATE products SET name=?,selling_price=?,active=? WHERE id=?').run(`Buffet: ${buffet.name}`,num(buffet.price),active?1:0,p.id);p=db.prepare('SELECT * FROM products WHERE id=?').get(p.id);}return p;}
