app.put('/api/restaurant/orders/:id',auth,allow('restaurant','pos'),(req,res)=>{const o=db.prepare('SELECT * FROM restaurant_orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});if(!enforceUnit(req,o.business_unit_id))return res.status(403).json({error:'Wrong business unit'});if(o.status!=='Open')return res.status(400).json({error:'Closed orders cannot be edited'});if(req.body.table_id!==undefined){const nt=req.body.table_id?db.prepare('SELECT * FROM restaurant_tables WHERE id=? AND business_unit_id=?').get(req.body.table_id,o.business_unit_id):null;if(nt&&nt.status!=='Available'&&nt.id!==o.table_id)return res.status(400).json({error:'Table is not available'});}const oldTable=o.table_id;const newTable=req.body.table_id===undefined?o.table_id:(req.body.table_id||null);const orderType=req.body.order_type??o.order_type;if(orderType==='Dine-in'&&!newTable)return res.status(400).json({error:'Dine-in orders require a table'});db.prepare('UPDATE restaurant_orders SET table_id=?,customer_name=?,order_type=? WHERE id=?').run(newTable,req.body.customer_name??o.customer_name,orderType,o.id);if(oldTable&&oldTable!==newTable)db.prepare("UPDATE restaurant_tables SET status='Available' WHERE id=? AND business_unit_id=?").run(oldTable,o.business_unit_id);if(newTable&&oldTable!==newTable)db.prepare("UPDATE restaurant_tables SET status='Busy' WHERE id=? AND business_unit_id=?").run(newTable,o.business_unit_id);if(req.body.items){db.prepare('DELETE FROM restaurant_order_items WHERE order_id=?').run(o.id);const add=db.prepare('INSERT INTO restaurant_order_items(order_id,product_id,item_name,quantity,unit_price,unit_cost,line_total,kitchen_status,notes) VALUES(?,?,?,?,?,?,?,?,?)');for(const it of req.body.items){const p=db.prepare('SELECT * FROM products WHERE id=? AND business_unit_id=?').get(it.product_id,o.business_unit_id);if(!p)return res.status(400).json({error:'Invalid menu item'});const q=num(it.quantity);if(q<=0)return res.status(400).json({error:'Invalid quantity'});const price=it.unit_price===undefined?p.selling_price:num(it.unit_price);add.run(o.id,p.id,p.name,q,price,p.cost_price,q*price,'Pending',it.notes||'');}}res.json({ok:true});});



function v23EnsureExcavatorSchema(){
  const tables = db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all().map(x=>x.name);
  if(!tables.includes('excavator_assets')) {
    db.exec(`CREATE TABLE IF NOT EXISTS excavator_assets(
      id INTEGER PRIMARY KEY AUTOINCREMENT,business_unit_id INTEGER NOT NULL,asset_no TEXT NOT NULL,
      type TEXT DEFAULT 'Excavator',make TEXT DEFAULT '',model TEXT DEFAULT '',year INTEGER,
      serial_no TEXT DEFAULT '',condition_status TEXT DEFAULT 'Used',status TEXT DEFAULT 'Available',
      lifecycle_stage TEXT DEFAULT 'Purchased',purchase_date TEXT,purchase_price REAL DEFAULT 0,
      customer_id INTEGER,selling_price REAL DEFAULT 0,notes TEXT DEFAULT '',created_by INTEGER,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(business_unit_id,asset_no)
    )`);
  }
  if(!tables.includes('excavator_transactions')) {
    db.exec(`CREATE TABLE IF NOT EXISTS excavator_transactions(
      id INTEGER PRIMARY KEY AUTOINCREMENT,asset_id INTEGER NOT NULL,type TEXT NOT NULL,stage TEXT NOT NULL,
      transaction_date TEXT,counterparty TEXT DEFAULT '',amount REAL DEFAULT 0,currency TEXT DEFAULT 'KRW',
      status TEXT DEFAULT 'Open',notes TEXT DEFAULT '',metadata TEXT DEFAULT '',created_by INTEGER,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);
  }
  const cols=(t)=>db.prepare(`PRAGMA table_info(${t})`).all().map(x=>x.name);
  const add=(t,c,d)=>{ if(!cols(t).includes(c)) db.exec(`ALTER TABLE ${t} ADD COLUMN ${c} ${d}`); };
  add('excavator_assets','lifecycle_stage',"TEXT DEFAULT 'Purchased'");
  add('excavator_assets','customer_id','INTEGER');
  add('excavator_assets','selling_price','REAL DEFAULT 0');
  add('excavator_assets','notes',"TEXT DEFAULT ''");
  add('excavator_assets','created_by','INTEGER');
  add('excavator_assets','created_at',"TEXT DEFAULT CURRENT_TIMESTAMP");
  add('excavator_transactions','currency',"TEXT DEFAULT 'KRW'");
  add('excavator_transactions','status',"TEXT DEFAULT 'Open'");
  add('excavator_transactions','notes',"TEXT DEFAULT ''");
  add('excavator_transactions','metadata',"TEXT DEFAULT ''");
  add('excavator_transactions','created_by','INTEGER');
  add('excavator_transactions','created_at',"TEXT DEFAULT CURRENT_TIMESTAMP");
  if(!tables.includes('excavator_lifecycle_events')) db.exec(`CREATE TABLE IF NOT EXISTS excavator_lifecycle_events(
    id INTEGER PRIMARY KEY AUTOINCREMENT,asset_id INTEGER NOT NULL,from_stage TEXT,to_stage TEXT NOT NULL,
    note TEXT DEFAULT '',user_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP
  )`);
}
try{v23EnsureExcavatorSchema();}catch(e){console.error('V23 schema repair:',e.message);}
