function excavatorGuard(req,res){
  const b=currentUnit(req);
  const unit=db.prepare("SELECT id FROM business_units WHERE id=? AND name='Excavator' AND status!='Archived'").get(b);
  if(!unit){res.status(400).json({error:'Select the Excavator business unit first.'});return null;}
  return b;
}
app.get('/api/excavator/dashboard',auth,allow('dashboard'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;
  const assets=db.prepare('SELECT COUNT(*) c FROM excavator_assets WHERE business_unit_id=?').get(b).c;
  const available=db.prepare("SELECT COUNT(*) c FROM excavator_assets WHERE business_unit_id=? AND status='Available'").get(b).c;
  const sold=db.prepare("SELECT COUNT(*) c FROM excavator_assets WHERE business_unit_id=? AND status='Sold'").get(b).c;
  const purchase=db.prepare('SELECT COALESCE(SUM(purchase_price),0) v FROM excavator_assets WHERE business_unit_id=?').get(b).v;
  const repairs=db.prepare('SELECT COALESCE(SUM(r.amount),0) v FROM excavator_repairs r JOIN excavator_assets a ON a.id=r.asset_id WHERE a.business_unit_id=?').get(b).v;
  const logistics=db.prepare('SELECT COALESCE(SUM(l.amount),0) v FROM excavator_logistics l JOIN excavator_assets a ON a.id=l.asset_id WHERE a.business_unit_id=?').get(b).v;
  const sales=db.prepare("SELECT COALESCE(SUM(selling_price),0) v FROM excavator_assets WHERE business_unit_id=? AND status='Sold'").get(b).v;
  const receivable=db.prepare("SELECT COALESCE(SUM(amount),0) v FROM excavator_payments p JOIN excavator_assets a ON a.id=p.asset_id WHERE a.business_unit_id=? AND p.payment_type='Sale' AND p.status!='Paid'").get(b).v;
  const payable=db.prepare("SELECT COALESCE(SUM(amount),0) v FROM excavator_payments p JOIN excavator_assets a ON a.id=p.asset_id WHERE a.business_unit_id=? AND p.payment_type='Purchase' AND p.status!='Paid'").get(b).v;
  const margin=sales-(purchase+repairs+logistics);
  const pendingDocs=db.prepare("SELECT COUNT(*) c FROM documents WHERE business_unit_id=? AND approved=0").get(b).c;
  res.json({assets,available,sold,purchase,repairs,logistics,sales,margin,receivable,payable,pendingDocs});
});
app.get('/api/excavator/save-check',auth,allow('dashboard','sales','purchases','inventory','finance'),(req,res)=>{
  try{
    v23EnsureExcavatorSchema();
    const b=excavatorGuard(req,res); if(!b)return;
    const assetCols=db.prepare('PRAGMA table_info(excavator_assets)').all().map(x=>x.name);
    const txCols=db.prepare('PRAGMA table_info(excavator_transactions)').all().map(x=>x.name);
    const lifeCols=db.prepare('PRAGMA table_info(excavator_lifecycle_events)').all().map(x=>x.name);
    res.json({ok:true,business_unit_id:b,
      assets_required:['business_unit_id','asset_no','type','make','model','purchase_date','purchase_price','created_by'].every(x=>assetCols.includes(x)),
      transactions_required:['asset_id','type','stage','transaction_date','amount','currency','status','metadata','created_by'].every(x=>txCols.includes(x)),
      lifecycle_required:['asset_id','to_stage','user_id'].every(x=>lifeCols.includes(x))
    });
  }catch(e){res.status(500).json({ok:false,error:e.message})}
});
function excavatorAssetForAction(req,res,id,b,action){
  const a=db.prepare('SELECT a.*, b.name buyer_name FROM excavator_assets a LEFT JOIN excavator_buyers b ON b.id=a.buyer_id WHERE a.id=? AND a.business_unit_id=?').get(Number(id),b);
  if(!a){res.status(404).json({error:'Machine not found'});return null;}
  if(a.lifecycle_stage==='Sold / Completed' && req.user.role!=='CEO / Owner'){
    res.status(403).json({error:`This machine is already sold. ${action} is available only to the CEO.`});return null;
  }
  return a;
}
app.get('/api/excavator/assets',auth,allow('dashboard','sales','purchases','inventory','finance','documents'),(req,res)=>{
  const b=excavatorGuard(req,res);if(!b)return;
  const sql=`SELECT a.*,
    COALESCE(NULLIF(a.machine_name,''),TRIM(COALESCE(a.make,'')||' '||COALESCE(a.model,''))) machine_display_name,
    c.company customer_name,
    s.name supplier_name,s.location supplier_location,s.contact_person supplier_contact_person,s.phone supplier_phone,s.email supplier_email,s.address supplier_address,
    COALESCE((SELECT SUM(amount) FROM excavator_repairs r WHERE r.asset_id=a.id),0) repair_cost,
    COALESCE((SELECT SUM(amount) FROM excavator_logistics l WHERE l.asset_id=a.id),0) logistics_cost,
    COALESCE((SELECT SUM(CASE WHEN p.status NOT IN ('Sold','Exported') THEN p.cost ELSE 0 END) FROM excavator_parts p WHERE p.asset_id=a.id),0) parts_cost,
    COALESCE((SELECT SUM(CASE WHEN t.status!='Cancelled' AND (t.metadata IS NULL OR t.metadata='' OR json_extract(t.metadata,'$.include_in_machine_cost') IS NOT 0) THEN t.amount ELSE 0 END)
      FROM excavator_transactions t WHERE t.asset_id=a.id
      AND t.type IN ('Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost')),0) total_cost,
    COALESCE((SELECT SUM(CASE WHEN t.status!='Cancelled' THEN t.amount ELSE 0 END)
      FROM excavator_transactions t WHERE t.asset_id=a.id AND t.type IN ('Local Sale','Export Sale')),0) sale_amount,
    COALESCE((SELECT SUM(amount) FROM excavator_payments p WHERE p.asset_id=a.id AND p.payment_type='Purchase' AND p.status='Paid'),0) purchase_paid,
    COALESCE((SELECT SUM(amount) FROM excavator_payments p WHERE p.asset_id=a.id AND p.payment_type='Sale' AND p.status='Paid'),0) sale_paid,
    COALESCE((SELECT COUNT(*) FROM excavator_documents d WHERE d.asset_id=a.id),0) document_count
    FROM excavator_assets a
    LEFT JOIN customers c ON c.id=a.customer_id
    LEFT JOIN excavator_suppliers s ON s.id=a.supplier_id
    WHERE a.business_unit_id=? ORDER BY a.id DESC`;
  const rows=db.prepare(sql).all(b).map(x=>{
    const sale=Number(x.sale_amount||0), paid=Number(x.sale_paid||0), cost=Number(x.total_cost||0);
    const payment_status=sale<=0?'Not Sold':(paid>=sale?'Paid':(paid>0?'Partially Paid':'Pending'));
    const outstanding=Math.max(0,sale-paid);
    const purchasePrice=Number(x.purchase_price||0), purchasePaid=Number(x.purchase_paid||0);
    const purchaseOutstanding=Math.max(0,purchasePrice-purchasePaid);
    const purchaseStatus=purchasePrice<=0?'Unknown':purchasePaid>=purchasePrice?'Paid':purchasePaid>0?'Token/Partial Paid':'Pending';
    return {...x,total_cost:cost,sale_amount:sale,sale_paid:paid,sale_outstanding:outstanding,
      sale_payment_status:payment_status,profit_loss:sale-cost,
      profit_loss_status:sale<=0?'Not Sold':(sale-cost>=0?'Profit':'Loss'),
      purchase_paid:purchasePaid,purchase_outstanding:purchaseOutstanding,purchase_status:purchaseStatus};
  });
  res.json(rows);
});
function markMatchingSupplierListingsUnavailable(supplierId, machine){
  if(!supplierId)return 0;
  const rows=db.prepare(`SELECT id,machine_name,make,model,serial_no FROM excavator_supplier_machines WHERE supplier_id=? AND status='Available'`).all(supplierId);
  const norm=v=>String(v||'').trim().toLowerCase(); let count=0;
  for(const r of rows){
    const serial=norm(machine.serial_no), rserial=norm(r.serial_no);
    const exactSerial=serial && rserial && serial===rserial;
    const exactDetails=norm(r.machine_name)===norm(machine.machine_name)&&norm(r.make)===norm(machine.make)&&norm(r.model)===norm(machine.model);
    if(exactSerial||exactDetails){db.prepare("UPDATE excavator_supplier_machines SET status='Purchased' WHERE id=?").run(r.id);count++;}
  }
  return count;
}
function markMatchingSupplierListingsSold(asset){return asset?.supplier_id?markMatchingSupplierListingsUnavailable(asset.supplier_id,asset):0;}
app.post('/api/excavator/assets',auth,allow('sales','purchases','inventory','finance'),(req,res)=>{
  try{
    v23EnsureExcavatorSchema();
    const b=excavatorGuard(req,res); if(!b)return;
    const assetNo=String(req.body.asset_no||'').trim();
    const type=String(req.body.type||'Excavator').trim();
    if(!assetNo)return res.status(400).json({error:'Machine / Deal No. is required.'});
    if(!String(req.body.machine_name||'').trim())return res.status(400).json({error:'Machine Name is required.'});
    if(!String(req.body.make||'').trim())return res.status(400).json({error:'Make is required.'});
    if(!String(req.body.model||'').trim())return res.status(400).json({error:'Model is required.'});
    if(!req.body.purchase_date)return res.status(400).json({error:'Purchase date is required.'});
    const price=num(req.body.purchase_price);
    if(price<=0)return res.status(400).json({error:'Purchase price must be greater than zero.'});
    const exists=db.prepare('SELECT id FROM excavator_assets WHERE business_unit_id=? AND asset_no=?').get(b,assetNo);
    if(exists)return res.status(409).json({error:'Machine / Deal No. already exists in Excavator. Please use a different number.'});

    const tx=db.transaction(()=>{
      let supplierId=req.body.supplier_id?Number(req.body.supplier_id):null;
      let newSupplier=false;
      if(supplierId){
        const s=db.prepare('SELECT id FROM excavator_suppliers WHERE id=? AND business_unit_id=? AND active=1').get(supplierId,b);
        if(!s) throw new Error('Selected supplier was not found in this Excavator business unit.');
      } else if(String(req.body.supplier_option||'')==='Other / New Supplier' || String(req.body.supplier_name||'').trim()){
        const name=String(req.body.supplier_name||'').trim();
        if(!name) throw new Error('Supplier name is required for a new supplier.');
        const sr=db.prepare('INSERT INTO excavator_suppliers(business_unit_id,name,location,contact_person,phone,email,address,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)').run(
          b,name,req.body.supplier_location||'',req.body.supplier_contact_person||'',req.body.supplier_phone||'',
          req.body.supplier_email||'',req.body.supplier_address||'',req.body.supplier_notes||'',req.user.id);
        supplierId=Number(sr.lastInsertRowid); newSupplier=true;
      }

      const token=Math.max(0,num(req.body.purchase_token));
      const balance=Math.max(0,price-token);
      const purchaseStatus=token>=price?'Paid':token>0?'Token Paid / Balance Pending':'Pending';

      const r=db.prepare(`INSERT INTO excavator_assets(
        business_unit_id,asset_no,machine_name,type,make,model,year,serial_no,condition_status,status,lifecycle_stage,
        purchase_date,purchase_price,customer_id,selling_price,supplier_id,purchase_token,purchase_balance,purchase_payment_status,notes,created_by)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(
        b,assetNo,String(req.body.machine_name||''),type,String(req.body.make||''),String(req.body.model||''),
        req.body.year?Number(req.body.year):null,String(req.body.serial_no||''),String(req.body.condition_status||'Used'),
        'Available','Purchased',String(req.body.purchase_date),price,null,0,supplierId,token,balance,purchaseStatus,
        String(req.body.notes||''),req.user.id);

      const assetId=Number(r.lastInsertRowid);
      markMatchingSupplierListingsUnavailable(supplierId,{machine_name:req.body.machine_name,make:req.body.make,model:req.body.model,serial_no:req.body.serial_no});
      const supplier=db.prepare('SELECT * FROM excavator_suppliers WHERE id=?').get(supplierId||0);
      db.prepare(`INSERT INTO excavator_transactions
        (asset_id,type,stage,transaction_date,counterparty,amount,currency,status,notes,metadata,created_by)
        VALUES(?,?,?,?,?,?,?,?,?,?,?)`).run(
          assetId,'Purchase','Purchased',String(req.body.purchase_date),
          supplier?.name || String(req.body.seller||''),price,'KRW','Open',String(req.body.notes||''),
          JSON.stringify({include_in_machine_cost:true,purchase_token:token,purchase_balance:balance,documentation_required:true}),req.user.id);

      db.prepare(`INSERT INTO excavator_lifecycle_events(asset_id,from_stage,to_stage,note,user_id)
        VALUES(?,?,?,?,?)`).run(assetId,null,'Purchased','Machine purchased',req.user.id);

      if(token>0){
        const p=db.prepare('INSERT INTO excavator_payments(asset_id,payment_type,amount,paid_date,status,method,reference,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)')
          .run(assetId,'Purchase',token,req.body.token_paid_date||req.body.purchase_date,'Paid',req.body.token_payment_method||'Bank',
            req.body.token_payment_reference||'','Purchase token payment',req.user.id);
        db.prepare('INSERT INTO finance_entries(business_unit_id,type,category,amount,description,status,payment_method,reference,created_by,verification_status,source_type,source_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')
          .run(b,'Expense','Excavator Purchase Token',token,'Token payment for '+assetNo,'Recorded',req.body.token_payment_method||'Bank',
            req.body.token_payment_reference||assetNo,req.user.id,'Pending Verification','Excavator Payment',p.lastInsertRowid);
      }

      // Purchase commitment is represented in the machine transaction/cost, while Finance records actual cash payment.
      const reqs=db.prepare(`SELECT r.*,s.name supplier_name FROM excavator_supplier_requirements r
        JOIN excavator_suppliers s ON s.id=r.supplier_id
        WHERE s.business_unit_id=? AND r.status='Active'`).all(b);

      const machine={type,make:String(req.body.make||''),model:String(req.body.model||''),year:req.body.year?Number(req.body.year):null,price};
      let matchCount=0;
      for(const rq of reqs){
        const okType=!rq.machine_type||rq.machine_type.toLowerCase()===machine.type.toLowerCase();
        const okMake=!rq.make||rq.make.toLowerCase()===machine.make.toLowerCase();
        const okModel=!rq.model||rq.model.toLowerCase()===machine.model.toLowerCase();
        const okMin=!rq.min_year||machine.year>=rq.min_year;
        const okMax=!rq.max_year||machine.year<=rq.max_year;
        const okBudget=!rq.budget_max||machine.price<=rq.budget_max;
        if(okType&&okMake&&okModel&&okMin&&okMax&&okBudget){
          matchCount++;
          const users=db.prepare(`SELECT id FROM users WHERE active=1 AND business_unit_id=?`).all(b);
          for(const u of users){
            notify(u.id,'info','Supplier requirement match',
              `${rq.supplier_name} wants ${machine.make} ${machine.model} (${rq.action_type}).${rq.exchange_machine?' Exchange offered: '+rq.exchange_machine+'.':''} New machine: ${assetNo}.`);
          }
        }
      }

      if(newSupplier){
        notify(req.user.id,'success','Supplier added for future use',
          `${req.body.supplier_name} was added to the Excavator Suppliers list and linked to ${assetNo}.`);
      }
      if(matchCount){
        notify(req.user.id,'info','Supplier requirement match',
          `${matchCount} active supplier requirement(s) match newly purchased machine ${assetNo}.`);
      }

      audit(req.user,'excavator_asset',assetId,'create',assetNo);
      return {assetId,newSupplier,matchCount};
    });

    const result=tx();
    res.status(201).json({ok:true,id:result.assetId,new_supplier:result.newSupplier,requirement_matches:result.matchCount});
  }catch(e){
    console.error('POST /api/excavator/assets:',e);
    if(String(e.message).includes('UNIQUE')) return res.status(409).json({error:'Machine / Deal No. already exists in Excavator. Please use a different number.'});
    res.status(500).json({error:'Machine could not be saved. '+e.message});
  }
});
