app.post('/api/excavator/assets/:id/payments',auth,allow('finance','sales','purchases'),upload.array('receipt',10),(req,res)=>{
  const b=excavatorGuard(req,res);if(!b)return;
  const a=excavatorAssetForAction(req,res,req.params.id,b,'Payments');if(!a)return;
  const paymentType=req.body.payment_type||'Purchase', amount=num(req.body.amount);
  const paymentDate=String(req.body.payment_date||'').trim(), reference=String(req.body.reference||'').trim();
  if(amount<=0)return res.status(400).json({error:'Payment amount must be greater than zero.'});
  if(!paymentDate)return res.status(400).json({error:'Payment Date is required.'});
  if(!reference)return res.status(400).json({error:'Reference is required.'});
  const alreadyPaid=Number(db.prepare("SELECT COALESCE(SUM(amount),0) total FROM excavator_payments WHERE asset_id=? AND payment_type=? AND status='Paid'").get(a.id,paymentType).total||0);
  if(paymentType==='Purchase'){
    const purchasePrice=Number(a.purchase_price||0);
    if(alreadyPaid+amount>purchasePrice)return res.status(400).json({error:'Purchase payments cannot exceed the agreed purchase price.'});
    if(alreadyPaid+amount>=purchasePrice){
      const docCount=Number(db.prepare('SELECT COUNT(*) c FROM excavator_documents WHERE asset_id=?').get(a.id).c||0);
      if(docCount<=0)return res.status(400).json({error:'Required purchase documentation must be uploaded before the final purchase payment can be recorded.'});
    }
  }
  const tx=db.transaction(()=>{
    const r=db.prepare('INSERT INTO excavator_payments(asset_id,payment_type,amount,due_date,paid_date,status,method,reference,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')
      .run(a.id,paymentType,amount,null,paymentDate,'Paid',req.body.method||'Bank',reference,req.body.notes||'',req.user.id);
    const files=req.files||[]; let receiptId=null;
    if(files.length){
      const ins=db.prepare('INSERT INTO excavator_documents(asset_id,stage,transaction_type,transaction_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');
      for(const f of files){
        const dr=ins.run(a.id,'Payment','Payment',r.lastInsertRowid,`${paymentType} Payment Receipt · ${paymentDate} · ${reference} · KRW ${amount.toLocaleString()}`,f.originalname,'/uploads/'+f.filename,f.mimetype,f.size,req.user.id);
        receiptId=Number(dr.lastInsertRowid);
      }
      db.prepare('UPDATE excavator_payments SET receipt_document_id=? WHERE id=?').run(receiptId,r.lastInsertRowid);
    }
    const paid=Number(db.prepare("SELECT COALESCE(SUM(amount),0) total FROM excavator_payments WHERE asset_id=? AND payment_type=? AND status='Paid'").get(a.id,paymentType).total||0);
    if(paymentType==='Purchase'){
      const balance=Math.max(0,Number(a.purchase_price||0)-paid);
      const status=paid>=Number(a.purchase_price||0)?'Paid':paid>0?'Token/Partial Paid':'Pending';
      db.prepare('UPDATE excavator_assets SET purchase_token=CASE WHEN purchase_token>0 THEN purchase_token ELSE ? END,purchase_balance=?,purchase_payment_status=? WHERE id=?').run(paid,balance,status,a.id);
    }
    if(paymentType==='Sale'){
      // Sale payments are informational only; selling already completes the machine because 100% advance is taken outside this workflow.
      db.prepare("UPDATE excavator_assets SET status='Sold',lifecycle_stage='Sold / Completed' WHERE id=?").run(a.id);
    }
    db.prepare('INSERT INTO finance_entries(business_unit_id,type,category,amount,description,status,payment_method,reference,created_by,verification_status,source_type,source_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')
      .run(b,paymentType==='Sale'?'Revenue':'Expense','Excavator '+paymentType+' Payment',amount,'Excavator '+paymentType+' payment for '+a.asset_no,'Recorded',req.body.method||'Bank',reference,req.user.id,'Pending Verification','Excavator Payment',r.lastInsertRowid);
    audit(req.user,'excavator_payment',r.lastInsertRowid,'create',JSON.stringify({asset:a.asset_no,paymentType,amount,paymentDate,reference,receiptCount:files.length}));
    return {id:r.lastInsertRowid,receipt_document_id:receiptId};
  });
  try{res.json({ok:true,...tx()});}catch(e){console.error('Excavator payment:',e);res.status(400).json({error:e.message});}
});
app.delete('/api/excavator/assets/:id/payments/:paymentId',auth,allow('finance','sales','purchases'),(req,res)=>{
  const b=excavatorGuard(req,res);if(!b)return;
  const a=excavatorAssetForAction(req,res,req.params.id,b,'Delete payment');if(!a)return;
  const p=db.prepare('SELECT p.* FROM excavator_payments p JOIN excavator_assets a ON a.id=p.asset_id WHERE p.id=? AND p.asset_id=? AND a.business_unit_id=?').get(req.params.paymentId,req.params.id,b);
  if(!p)return res.status(404).json({error:'Payment record not found'});
  db.prepare('DELETE FROM excavator_payments WHERE id=?').run(p.id);
  if(p.payment_type==='Sale' && p.status==='Paid'){ const sale=Number(db.prepare("SELECT COALESCE(SUM(amount),0) total FROM excavator_transactions WHERE asset_id=? AND type IN ('Local Sale','Export Sale') AND status!='Cancelled'").get(a.id).total||0); const paid=Number(db.prepare("SELECT COALESCE(SUM(amount),0) total FROM excavator_payments WHERE asset_id=? AND payment_type='Sale' AND status='Paid'").get(a.id).total||0); if(sale>0 && paid<sale) db.prepare("UPDATE excavator_assets SET status='Sale Pending',lifecycle_stage='Sold / Payment Pending' WHERE id=?").run(a.id); }
  audit(req.user,'excavator_payment',p.id,'delete',JSON.stringify({asset_id:req.params.id,amount:p.amount,payment_type:p.payment_type}));
  res.json({ok:true});
});


