const EX_STAGES=['Purchased','Transport Pending','In Yard','Under Repair','Ready for Sale','Reserved','Local Sale','Export Preparation','Shipped','Exported','Sold / Payment Pending','Sold / Completed','On Hold','Cancelled'];
