    const columns=(table)=>db.prepare(`PRAGMA table_info(${table})`).all().map(x=>x.name);
    res.json({ok:true,unit:b,checks:{
      assets:has('excavator_assets'),
      transactions:has('excavator_transactions'),
      transaction_metadata:columns('excavator_transactions').includes('metadata'),
      transaction_currency:columns('excavator_transactions').includes('currency'),
      notifications:has('notifications'),
      notification_read_at:columns('notifications').includes('read_at')
    }});
