app.get('/api/excavator/runtime-check',auth,allow('dashboard','sales','purchases','inventory','finance'),(req,res)=>{
  try{
    const b=excavatorGuard(req,res); if(!b)return;
    const required=[
      ['excavator_assets',['id','business_unit_id','asset_no','make','model','purchase_date','purchase_price','created_by']],
      ['excavator_transactions',['id','asset_id','type','stage','transaction_date','amount','currency','status','metadata','created_by']],
      ['excavator_lifecycle_events',['id','asset_id','to_stage','user_id']],
      ['excavator_repairs',['id','asset_id','amount']],
      ['excavator_logistics',['id','asset_id','amount']],
      ['excavator_parts',['id','asset_id','cost']],
      ['excavator_payments',['id','asset_id','amount','payment_type','status']],
      ['excavator_documents',['id','asset_id','stage']]
    ];
    const checks={};
    for(const [table,cols] of required){
      const exists=!!db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name=?").get(table);
      const actual=exists?db.prepare(`PRAGMA table_info(${table})`).all().map(x=>x.name):[];
      checks[table]={exists,missing:cols.filter(x=>!actual.includes(x))};
    }
    res.json({ok:Object.values(checks).every(x=>x.exists&&!x.missing.length),business_unit_id:b,checks});
  }catch(e){console.error(e);res.status(500).json({ok:false,error:e.message})}
});
