app.get('/api/excavator/overview',auth,allow('dashboard'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;
  const assets=db.prepare('SELECT * FROM excavator_assets WHERE business_unit_id=? ORDER BY id DESC').all(b);
  const tx=db.prepare('SELECT * FROM excavator_transactions t JOIN excavator_assets a ON a.id=t.asset_id WHERE a.business_unit_id=? ORDER BY t.transaction_date DESC,t.id DESC').all(b);
  const costTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'];
  const included=(x)=>{if(!x.metadata)return true;try{return JSON.parse(x.metadata).include_in_machine_cost!==false}catch(e){return true}};
  const sum=(types,onlyIncluded=false)=>tx.filter(x=>types.includes(x.type)&&x.status!=='Cancelled'&&(!onlyIncluded||included(x))).reduce((n,x)=>n+Number(x.amount||0),0);
  const purchase=sum(['Purchase']), logistics=sum(['Logistics']), repair=sum(['Repair']), partCost=sum(['Part Purchase']), other=sum(['Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'],true);
  const sales=sum(['Local Sale','Export Sale']); const paidSale=sum(['Sale Payment']); const paidPurchase=sum(['Purchase Payment']);
  const open=assets.filter(a=>!['Sold / Completed','Cancelled'].includes(a.lifecycle_stage));
  const assetView=assets.map(a=>{const at=tx.filter(x=>x.asset_id===a.id&&x.status!=='Cancelled');const total=at.filter(x=>['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'].includes(x.type)&&included(x)).reduce((n,x)=>n+Number(x.amount||0),0);const sale=at.filter(x=>['Local Sale','Export Sale'].includes(x.type)).reduce((n,x)=>n+Number(x.amount||0),0);return {...a,total_cost:total,deal_profit:sale-total}});
  res.json({currency:'KRW',stages:EX_STAGES,summary:{machines:assets.length,open:open.length,inYard:assets.filter(a=>a.lifecycle_stage==='In Yard').length,repairing:assets.filter(a=>a.lifecycle_stage==='Under Repair').length,ready:assets.filter(a=>a.lifecycle_stage==='Ready for Sale').length,exporting:assets.filter(a=>['Export Preparation','Shipped','Exported'].includes(a.lifecycle_stage)).length,sold:assets.filter(a=>a.lifecycle_stage==='Sold / Completed').length,purchase,logistics,repair,partCost,other,totalCost:purchase+logistics+repair+partCost+other,sales,margin:sales-(purchase+logistics+repair+partCost+other),receivable:Math.max(0,sales-paidSale),payable:Math.max(0,purchase-paidPurchase)},assets:assetView});
});
