app.post('/api/excavator/assets/:id/complete-sale',auth,allow('sales','finance','purchases','inventory'),(req,res)=>{
  const b=excavatorGuard(req,res);if(!b)return;
  const a=db.prepare('SELECT a.*, b.name buyer_name FROM excavator_assets a LEFT JOIN excavator_buyers b ON b.id=a.buyer_id WHERE a.id=? AND a.business_unit_id=?').get(req.params.id,b);
  if(!a)return res.status(404).json({error:'Machine not found'});
  if(['Sold / Completed','Cancelled'].includes(a.lifecycle_stage))return res.status(400).json({error:'This machine is already closed.'});
  const paidPurchase=Number(db.prepare("SELECT COALESCE(SUM(amount),0) total FROM excavator_payments WHERE asset_id=? AND payment_type='Purchase' AND status='Paid'").get(a.id).total||0);
  if(paidPurchase < Number(a.purchase_price||0))return res.status(400).json({error:'This machine cannot be sold until the complete purchase price has been paid.'});
  const saleType=String(req.body.sale_type||'').trim();
  const saleDate=String(req.body.sale_date||'').trim();
  const customer=String(req.body.customer_name||'').trim();
  const buyerId=req.body.buyer_id?Number(req.body.buyer_id):null;
  if(buyerId && !db.prepare('SELECT id FROM excavator_buyers WHERE id=? AND business_unit_id=? AND active=1').get(buyerId,b))return res.status(400).json({error:'Invalid buyer selected.'});
  const amount=num(req.body.selling_price);
  const paymentDate=String(req.body.payment_date||'').trim();
  const paymentReference=String(req.body.payment_reference||'').trim();
  const destination=String(req.body.destination_country||'').trim();
  const shipping=String(req.body.shipping_reference||'').trim();
  const sellNote=String(req.body.sell_note||'').trim();
  if(!['Local Sale','Export Sale'].includes(saleType))return res.status(400).json({error:'Sale Type is required.'});
  if(!saleDate)return res.status(400).json({error:'Sale Date is required.'});
  if(!customer)return res.status(400).json({error:'Customer / Buyer is required.'});
  if(amount<=0)return res.status(400).json({error:'Selling Price is required and must be greater than zero.'});
  if(!paymentDate)return res.status(400).json({error:'Payment Date is required.'});
  if(!paymentReference)return res.status(400).json({error:'Payment Reference is required.'});
  if(!String(req.body.payment_method||'').trim())return res.status(400).json({error:'Payment Method is required.'});
  if(saleType==='Export Sale' && !destination)return res.status(400).json({error:'Destination Country is mandatory for export sales.'});
  if(!shipping)return res.status(400).json({error:'Shipping / Container Reference is required.'});
  const tx=db.transaction(()=>{
    let finalBuyerId=buyerId;
    let buyer;
    if(finalBuyerId){
      buyer=db.prepare('SELECT * FROM excavator_buyers WHERE id=? AND business_unit_id=? AND active=1').get(finalBuyerId,b);
      const available=Number(db.prepare('SELECT COALESCE((SELECT SUM(krw_amount) FROM excavator_buyer_payments WHERE buyer_id=?),0)-COALESCE((SELECT SUM(amount_krw) FROM excavator_buyer_payment_allocations WHERE buyer_id=?),0)-COALESCE((SELECT SUM(p2.krw_amount) FROM excavator_buyer_payments p2 WHERE p2.buyer_id=? AND p2.asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM excavator_buyer_payment_allocations al2 WHERE al2.payment_id=p2.id)),0) v').get(finalBuyerId,finalBuyerId,finalBuyerId).v||0);
      if(available < amount) throw new Error(`Buyer available advance is insufficient. Available: KRW ${available.toLocaleString()} / Required: KRW ${amount.toLocaleString()}. Record the buyer payment first.`);
    } else {
      const buyerType=String(req.body.new_buyer_type||'International')==='Local'?'Local':'International';
      const buyerName=String(req.body.new_buyer_name||customer).trim();
      const buyerCountry=String(req.body.new_buyer_country||destination||'').trim();
      if(!buyerName) throw new Error('New buyer name is required.');
      if(!buyerCountry) throw new Error('New buyer country is required.');
      const br=db.prepare(`INSERT INTO excavator_buyers(business_unit_id,name,country,location,contact_person,phone,whatsapp,email,address,payment_terms,notes,buyer_type,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(b,buyerName,buyerCountry,req.body.new_buyer_location||'',req.body.new_buyer_contact_person||'',req.body.new_buyer_phone||'',req.body.new_buyer_whatsapp||'',req.body.new_buyer_email||'',req.body.new_buyer_address||'',req.body.new_buyer_payment_terms||'',req.body.new_buyer_notes||'',buyerType,req.user.id);
      finalBuyerId=Number(br.lastInsertRowid);
      buyer=db.prepare('SELECT * FROM excavator_buyers WHERE id=?').get(finalBuyerId);
      const currency=String(req.body.payment_currency||'KRW').toUpperCase(); const fx=currency==='KRW'?1:num(req.body.payment_fx_rate);
      if(fx<=0)throw new Error('Conversion rate is required for the new buyer payment.');
      const original=currency==='KRW'?amount:amount/fx;
      const krw=currency==='KRW'?amount:original*fx;
      const pr=db.prepare(`INSERT INTO excavator_buyer_payments(buyer_id,payment_type,original_amount,currency,fx_rate,krw_amount,payment_date,method,reference,receipt_file,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).run(finalBuyerId,'Advance',original,currency,fx,krw,paymentDate,String(req.body.payment_method||'Bank'),paymentReference,'','Created from completed machine sale',req.user.id);
      db.prepare(`INSERT INTO excavator_buyer_payment_allocations(payment_id,buyer_id,asset_id,amount_krw,allocation_date,created_by,notes) VALUES(?,?,?,?,?,?,?)`).run(pr.lastInsertRowid,finalBuyerId,a.id,amount,paymentDate,req.user.id,'Allocated to machine sale at completion');
    }
    if(finalBuyerId && buyerId){
      let remaining=amount;
      const pays=db.prepare(`SELECT p.id,p.krw_amount,p.asset_id,COALESCE((SELECT SUM(al.amount_krw) FROM excavator_buyer_payment_allocations al WHERE al.payment_id=p.id),0) allocated FROM excavator_buyer_payments p WHERE p.buyer_id=? ORDER BY date(p.payment_date),p.id`).all(finalBuyerId);
      for(const p of pays){ if(remaining<=0)break; const legacyUsed=p.asset_id && !Number(p.allocated||0); const avail=Math.max(0,Number(p.krw_amount||0)-Number(p.allocated||0)-(legacyUsed?Number(p.krw_amount||0):0)); if(avail<=0)continue; const take=Math.min(avail,remaining); db.prepare(`INSERT INTO excavator_buyer_payment_allocations(payment_id,buyer_id,asset_id,amount_krw,allocation_date,created_by,notes) VALUES(?,?,?,?,?,?,?)`).run(p.id,finalBuyerId,a.id,take,paymentDate,req.user.id,'Allocated to machine sale'); remaining-=take; }
      if(remaining>0)throw new Error('Unable to allocate the buyer advance to this machine.');
    }
    const metadata={destination_country:destination,shipping_reference:shipping,customer_name:customer,payment_date:paymentDate,payment_reference:paymentReference,payment_method:String(req.body.payment_method||''),sell_note:sellNote,buyer_id:finalBuyerId,buyer_advance_allocated_krw:amount};
    const r=db.prepare('INSERT INTO excavator_transactions(asset_id,type,stage,transaction_date,counterparty,amount,currency,status,notes,metadata,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(a.id,saleType,'Sold / Completed',saleDate,customer,amount,'KRW','Completed',req.body.notes||'',JSON.stringify(metadata),req.user.id);
    db.prepare('INSERT INTO finance_entries(business_unit_id,type,category,amount,description,status,payment_method,reference,created_by,verification_status,source_type,source_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').run(b,'Revenue','Excavator Machine Sale',amount,'Excavator sale '+a.asset_no,'Recorded',String(req.body.payment_method||''),paymentReference,req.user.id,'Pending Verification','Excavator Sale',r.lastInsertRowid);
    db.prepare("UPDATE excavator_assets SET selling_price=?,customer_id=NULL,buyer_id=?,status='Sold',lifecycle_stage='Sold / Completed' WHERE id=? AND business_unit_id=?").run(amount,finalBuyerId,a.id,b);
    markMatchingSupplierListingsSold(a);
    db.prepare('INSERT INTO excavator_lifecycle_events(asset_id,from_stage,to_stage,note,user_id) VALUES(?,?,?,?,?)').run(a.id,a.lifecycle_stage,'Sold / Completed',saleType+' completed; buyer advance allocated',req.user.id);
    const supplier=a.supplier_id?db.prepare('SELECT * FROM excavator_suppliers WHERE id=? AND business_unit_id=?').get(a.supplier_id,b):null;
    const transactions=db.prepare("SELECT * FROM excavator_transactions WHERE asset_id=? AND status!='Cancelled' ORDER BY transaction_date ASC,id ASC").all(a.id);
    const costTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'];
    const includedCost=(x)=>{if(!x.metadata)return true;try{return JSON.parse(x.metadata).include_in_machine_cost!==false}catch(e){return true}};
    const costs=transactions.filter(x=>costTypes.includes(x.type)&&includedCost(x)); const totalCost=costs.reduce((n,x)=>n+Number(x.amount||0),0);
    const purchasePayments=db.prepare("SELECT * FROM excavator_payments WHERE asset_id=? AND payment_type='Purchase' ORDER BY paid_date,due_date,id").all(a.id);
    const salePayments=db.prepare("SELECT * FROM excavator_payments WHERE asset_id=? AND payment_type='Sale' ORDER BY paid_date,due_date,id").all(a.id);
    const allocations=db.prepare(`SELECT al.*,p.payment_date,p.reference,p.currency,p.original_amount FROM excavator_buyer_payment_allocations al JOIN excavator_buyer_payments p ON p.id=al.payment_id WHERE al.asset_id=? ORDER BY al.id`).all(a.id);
    buyer=db.prepare('SELECT * FROM excavator_buyers WHERE id=?').get(finalBuyerId);
    const parts=db.prepare('SELECT * FROM excavator_parts WHERE asset_id=? ORDER BY purchase_date,id').all(a.id); const repairs=db.prepare('SELECT * FROM excavator_repairs WHERE asset_id=? ORDER BY repair_date,id').all(a.id); const logistics=db.prepare('SELECT * FROM excavator_logistics WHERE asset_id=? ORDER BY logistics_date,id').all(a.id); const documents=db.prepare('SELECT * FROM excavator_documents WHERE asset_id=? ORDER BY created_at,id').all(a.id); const history=db.prepare('SELECT e.*,u.name user_name FROM excavator_lifecycle_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.asset_id=? ORDER BY e.created_at,id').all(a.id);
    const report={asset:{...a,supplier_name:supplier?.name||'',supplier_location:supplier?.location||'',supplier_phone:supplier?.phone||'',supplier_address:supplier?.address||'',purchase_paid:paidPurchase},machineDisplay:[a.machine_name,a.make,a.model].filter(Boolean).join(' ')||a.asset_no,supplier,buyer,customer,destination,shipping,saleType,saleDate,amount,saleAmount:amount,paymentDate,paymentReference,paymentMethod:String(req.body.payment_method||''),notes:String(req.body.notes||''),sellNote,totalCost,profit:amount-totalCost,costs,purchasePayments,salePayments,allocations,parts,repairs,logistics,documents,history,salePaid:amount,money:n=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})};
    const pdf=salePdfBuffer(report); const filename=`excavator-sale-${a.asset_no.replace(/[^a-z0-9_-]/gi,'_')}-${Date.now()}.pdf`; fs.writeFileSync(path.join(uploads,filename),pdf);
    const doc=db.prepare('INSERT INTO excavator_documents(asset_id,stage,transaction_type,transaction_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?,?)').run(a.id,saleType==='Local Sale'?'Local Sale':'Export Preparation',saleType,r.lastInsertRowid,'Machine Sale Document',filename,'/uploads/'+filename,'application/pdf',pdf.length,req.user.id);
    audit(req.user,'excavator_sale',r.lastInsertRowid,'complete',JSON.stringify({asset:a.asset_no,saleType,amount,pdf_document_id:doc.lastInsertRowid,buyer_id:finalBuyerId,advance_allocated_krw:amount}));
    return {transaction_id:r.lastInsertRowid,document_id:doc.lastInsertRowid,document_url:'/uploads/'+filename,buyer_id:finalBuyerId,advance_allocated_krw:amount};
  });
  try{res.json({ok:true,...tx(),stage:'Sold / Completed'});}catch(e){console.error('Excavator complete sale:',e);res.status(400).json({error:e.message});}
});
app.post('/api/excavator/assets/:id/transactions',auth,allow('sales','purchases','inventory','finance'),upload.array('files',30),(req,res)=>{
  const b=excavatorGuard(req,res);if(!b)return;
  const a=excavatorAssetForAction(req,res,req.params.id,b,'Costs and transaction changes');if(!a)return;
  const type=String(req.body.type||'').trim(),stage=String(req.body.stage||a.lifecycle_stage||'Purchased').trim();
  const allowed=['Purchase','Logistics','Repair','Part Purchase','Part Used','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost','Local Sale','Export Sale','Purchase Payment','Sale Payment'];
  if(!allowed.includes(type))return res.status(400).json({error:'Invalid transaction type'});
  const amount=num(req.body.amount);
  let metadata={};
  if(req.body.metadata){try{metadata=typeof req.body.metadata==='string'?JSON.parse(req.body.metadata):req.body.metadata}catch(e){metadata={}}}
  if(req.body.include_in_machine_cost!==undefined)metadata.include_in_machine_cost=String(req.body.include_in_machine_cost)==='1';
  const tx=db.transaction(()=>{
    const r=db.prepare('INSERT INTO excavator_transactions(asset_id,type,stage,transaction_date,counterparty,amount,currency,status,notes,metadata,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(a.id,type,stage,req.body.transaction_date||null,req.body.counterparty||'',amount,req.body.currency||'KRW',req.body.status||'Open',req.body.notes||'',JSON.stringify(metadata),req.user.id);
    let documentCount=0;
    const files=req.files||[];
    const ins=db.prepare('INSERT INTO excavator_documents(asset_id,stage,transaction_type,transaction_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');
    for(const f of files){ins.run(a.id,stage,type,r.lastInsertRowid,type+' supporting document',f.originalname,'/uploads/'+f.filename,f.mimetype,f.size,req.user.id);documentCount++}
    audit(req.user,'excavator_transaction',r.lastInsertRowid,'create',JSON.stringify({asset:a.asset_no,type,stage,amount,documentCount}));
    return {id:r.lastInsertRowid,document_count:documentCount};
  });
  try{res.json(tx())}catch(e){console.error('Excavator transaction:',e);res.status(400).json({error:e.message});}
});
app.put('/api/excavator/assets/:id/transactions/:txid',auth,allow('sales','purchases','inventory','finance'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const a=excavatorAssetForAction(req,res,req.params.id,b,'Costs and transaction changes');if(!a)return;const x=db.prepare('SELECT * FROM excavator_transactions WHERE id=? AND asset_id=?').get(req.params.txid,a.id);if(!x)return res.status(404).json({error:'Transaction not found'});db.prepare('UPDATE excavator_transactions SET type=?,stage=?,transaction_date=?,counterparty=?,amount=?,currency=?,status=?,notes=?,metadata=? WHERE id=?').run(req.body.type??x.type,req.body.stage??x.stage,req.body.transaction_date??x.transaction_date,req.body.counterparty??x.counterparty,num(req.body.amount??x.amount),req.body.currency??x.currency,req.body.status??x.status,req.body.notes??x.notes,req.body.metadata?JSON.stringify(req.body.metadata):x.metadata,x.id);audit(req.user,'excavator_transaction',x.id,'update',JSON.stringify(req.body));res.json({ok:true});});
