app.get('/api/excavator/buyers',auth,allow('dashboard','sales','purchases','finance'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const rows=db.prepare(`SELECT x.*, COALESCE((SELECT SUM(p.krw_amount) FROM excavator_buyer_payments p WHERE p.buyer_id=x.id),0) total_paid_krw, COALESCE((SELECT SUM(al.amount_krw) FROM excavator_buyer_payment_allocations al WHERE al.buyer_id=x.id),0)+COALESCE((SELECT SUM(p2.krw_amount) FROM excavator_buyer_payments p2 WHERE p2.buyer_id=x.id AND p2.asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM excavator_buyer_payment_allocations al2 WHERE al2.payment_id=p2.id)),0) allocated_krw, COALESCE((SELECT COUNT(*) FROM excavator_assets a WHERE a.buyer_id=x.id AND a.business_unit_id=x.business_unit_id),0) machine_count FROM excavator_buyers x WHERE x.business_unit_id=? AND x.active=1 ORDER BY x.name`).all(b).map(x=>({...x,unallocated_advance_krw:Math.max(0,Number(x.total_paid_krw||0)-Number(x.allocated_krw||0))}));res.json(rows);});
