app.get('/api/excavator/buyers/:id',auth,allow('dashboard','sales','purchases','finance'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const x=db.prepare('SELECT * FROM excavator_buyers WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!x)return res.status(404).json({error:'Buyer not found'});const payments=db.prepare(`SELECT p.*,a.asset_no,a.machine_name,COALESCE((SELECT SUM(al.amount_krw) FROM excavator_buyer_payment_allocations al WHERE al.payment_id=p.id),0) allocated_krw, MAX(p.krw_amount-COALESCE((SELECT SUM(al.amount_krw) FROM excavator_buyer_payment_allocations al WHERE al.payment_id=p.id),0)-CASE WHEN p.asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM excavator_buyer_payment_allocations alx WHERE alx.payment_id=p.id) THEN p.krw_amount ELSE 0 END,0) available_krw FROM excavator_buyer_payments p LEFT JOIN excavator_assets a ON a.id=p.asset_id WHERE p.buyer_id=? ORDER BY p.payment_date DESC,p.id DESC`).all(x.id);const machines=db.prepare(`SELECT a.id,a.asset_no,a.machine_name,a.make,a.model,a.purchase_price,a.selling_price,a.lifecycle_stage,a.status FROM excavator_assets a WHERE a.buyer_id=? AND a.business_unit_id=? ORDER BY a.id DESC`).all(x.id,b);const allocations=db.prepare(`SELECT al.*,p.payment_date,p.reference,p.currency,p.original_amount,a.asset_no,a.machine_name FROM excavator_buyer_payment_allocations al JOIN excavator_buyer_payments p ON p.id=al.payment_id JOIN excavator_assets a ON a.id=al.asset_id WHERE al.buyer_id=? AND a.business_unit_id=? ORDER BY al.allocation_date DESC,al.id DESC`).all(x.id,b);const reqs=db.prepare('SELECT * FROM excavator_buyer_requirements WHERE buyer_id=? ORDER BY id DESC').all(x.id);const docs=db.prepare('SELECT * FROM excavator_buyer_documents WHERE buyer_id=? ORDER BY id DESC').all(x.id);let resaleShares=[];if(String(x.country||'').trim().toLowerCase()==='pakistan')resaleShares=db.prepare(`SELECT r.*,a.asset_no,a.machine_name FROM excavator_buyer_resale_shares r JOIN excavator_assets a ON a.id=r.asset_id WHERE r.buyer_id=? AND a.business_unit_id=? ORDER BY r.id DESC`).all(x.id,b);const total=db.prepare('SELECT COALESCE(SUM(krw_amount),0) v FROM excavator_buyer_payments WHERE buyer_id=?').get(x.id).v;const allocated=db.prepare('SELECT COALESCE((SELECT SUM(amount_krw) FROM excavator_buyer_payment_allocations WHERE buyer_id=?),0)+COALESCE((SELECT SUM(p2.krw_amount) FROM excavator_buyer_payments p2 WHERE p2.buyer_id=? AND p2.asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM excavator_buyer_payment_allocations al2 WHERE al2.payment_id=p2.id)),0) v').get(x.id,x.id).v;res.json({buyer:x,payments,machines,allocations,requirements:reqs,documents:docs,resale_shares:resaleShares,balance:{total_paid_krw:total,allocated_krw:allocated,available_advance_krw:Math.max(0,total-allocated)},resale_profit_eligible:String(x.country||'').trim().toLowerCase()==='pakistan'});});
app.post('/api/excavator/buyers/:id/payments',auth,allow('sales','purchases','finance'),upload.single('receipt'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const buyer=db.prepare('SELECT * FROM excavator_buyers WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!buyer)return res.status(404).json({error:'Buyer not found'});const original=num(req.body.original_amount);const currency=String(req.body.currency||'KRW').toUpperCase();const rate=currency==='KRW'?1:num(req.body.fx_rate);const date=String(req.body.payment_date||'').trim();const reference=String(req.body.reference||'').trim();if(original<=0)return res.status(400).json({error:'Payment amount is required'});if(!date)return res.status(400).json({error:'Payment Date is required'});if(!reference)return res.status(400).json({error:'Reference is required'});if(rate<=0)return res.status(400).json({error:'Conversion rate is required and must be greater than zero'});const krw=currency==='KRW'?original:original*rate;const assetId=req.body.asset_id?Number(req.body.asset_id):null;if(assetId&&!db.prepare('SELECT id FROM excavator_assets WHERE id=? AND business_unit_id=?').get(assetId,b))return res.status(400).json({error:'Invalid machine/deal'});const tx=db.transaction(()=>{const r=db.prepare(`INSERT INTO excavator_buyer_payments(buyer_id,asset_id,payment_type,original_amount,currency,fx_rate,krw_amount,payment_date,method,reference,receipt_file,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?, ?,?)`).run(buyer.id,assetId,req.body.payment_type||'Advance',original,currency,rate,krw,date,req.body.method||'Bank',reference,req.file?.filename||'',req.body.notes||'',req.user.id);let docId=null;if(req.file){const d=db.prepare(`INSERT INTO excavator_buyer_documents(buyer_id,payment_id,asset_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?,?)`).run(buyer.id,r.lastInsertRowid,assetId,'Buyer Payment Receipt',req.file.originalname,'/uploads/'+req.file.filename,req.file.mimetype,req.file.size,req.user.id);docId=d.lastInsertRowid;db.prepare('UPDATE excavator_buyer_payments SET receipt_document_id=? WHERE id=?').run(docId,r.lastInsertRowid);}return {id:r.lastInsertRowid,krw_amount:krw,receipt_document_id:docId};});res.json(tx());});
