app.post('/api/excavator/buyers/:id/resale-shares',auth,allow('sales','finance','purchases'),upload.single('receipt'),(req,res)=>{const b=excavatorGuard(req,res);if(!b)return;const buyer=db.prepare('SELECT id,country FROM excavator_buyers WHERE id=? AND business_unit_id=?').get(req.params.id,b);if(!buyer)return res.status(404).json({error:'Buyer not found'});if(String(buyer.country||'').trim().toLowerCase()!=='pakistan')return res.status(403).json({error:'Resale Profit Share is available only for Pakistani buyers.'});const assetId=Number(req.body.asset_id||0);if(!assetId)return res.status(400).json({error:'Machine is required'});if(!db.prepare("SELECT id FROM excavator_assets WHERE id=? AND business_unit_id=? AND lifecycle_stage='Sold / Completed'").get(assetId,b))return res.status(400).json({error:'Select a sold machine belonging to this business unit'});const resalePrice=num(req.body.resale_price_pkr),resaleProfit=num(req.body.resale_profit_pkr),sharePercent=num(req.body.share_percent),ourShare=num(req.body.our_share_pkr),received=num(req.body.amount_received_pkr),outstanding=Math.max(0,ourShare-received),receivedFlag=req.body.received==='1'||received>=ourShare&&ourShare>0?1:0;const tx=db.transaction(()=>{const r=db.prepare(`INSERT INTO excavator_buyer_resale_shares(buyer_id,asset_id,resale_price_pkr,resale_profit_pkr,share_percent,our_share_pkr,amount_received_pkr,outstanding_pkr,received,received_date,reference,receipt_file,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(buyer.id,assetId,resalePrice,resaleProfit,sharePercent,ourShare,received,outstanding,receivedFlag,req.body.received_date||null,req.body.reference||'',req.file?.filename||'',req.body.notes||'',req.user.id);let docId=null;if(req.file){const d=db.prepare(`INSERT INTO excavator_buyer_documents(buyer_id,asset_id,title,original_name,file_path,mime_type,size_bytes,uploaded_by) VALUES(?,?,?,?,?,?,?,?)`).run(buyer.id,assetId,'Buyer Resale Profit Share Receipt',req.file.originalname,'/uploads/'+req.file.filename,req.file.mimetype,req.file.size,req.user.id);docId=d.lastInsertRowid;db.prepare('UPDATE excavator_buyer_resale_shares SET receipt_document_id=? WHERE id=?').run(docId,r.lastInsertRowid);}return {id:r.lastInsertRowid,received:receivedFlag,outstanding_pkr:outstanding};});res.json(tx());});
